let soundEnabled = true;
let masterVolume = 1;
try {
  soundEnabled = localStorage.getItem('battleSoundEnabled') !== 'false';
  const savedVolume = Number(localStorage.getItem('battleMasterVolume'));
  if (Number.isFinite(savedVolume)) masterVolume = Math.max(0, Math.min(1, savedVolume));
} catch (_) {
  soundEnabled = true;
  masterVolume = 1;
}
let audioContext = null;
let masterGain = null;
let noiseBuffer = null;
const soundLastPlayed = new Map();
const soundSamples = {
  sniper: { src: 'assets/audio/sniper-rifle-blast.wav', volume: 0.1, playbackRate: 1 },
  sniperAbility: { src: 'assets/audio/sniper-rifle-blast.wav', volume: 0.12, playbackRate: 0.9 },
  banditBomb: { src: 'assets/audio/bomb-explosion.wav', volume: 0.07, playbackRate: 1.08 },
  infantryGrenade: { src: 'assets/audio/bomb-explosion.wav', volume: 0.08, playbackRate: 0.88 },
  bowDraw: { src: 'assets/audio/freesound_community-creakingnoise-35017.mp3', volume: 0.58, playbackRate: 1, startTime: 0.7, maxDuration: 1800 },
};
const soundSampleTemplates = new Map();
const activeSoundSamples = new Map();
const activeRoyalChargeWinds = new Set();
let gamePaused = false;
let suppressHiddenRoomAudio = false;

function stopAllSoundSamples() {
  for (const name of [...activeSoundSamples.keys()]) stopSoundSample(name);
  for (const fighter of [...activeRoyalChargeWinds]) stopRoyalChargeWind(fighter);
}

function stopSoundSample(name) {
  const active = activeSoundSamples.get(name);
  if (!active) return;
  clearTimeout(active.timeout);
  active.sample.pause();
  active.sample.currentTime = 0;
  activeSoundSamples.delete(name);
}

function playSoundSample(name) {
  const config = soundSamples[name];
  if (suppressHiddenRoomAudio) return false;
  if (!soundEnabled || !config) return false;
  stopSoundSample(name);
  let template = soundSampleTemplates.get(config.src);
  if (!template) {
    template = new Audio(config.src);
    template.preload = 'auto';
    soundSampleTemplates.set(config.src, template);
  }
  const sample = template.cloneNode();
  sample.volume = Math.max(0, Math.min(1, config.volume * masterVolume));
  sample.playbackRate = config.playbackRate;
  sample.currentTime = config.startTime || 0;
  sample.play().catch(() => {});
  const timeout = config.maxDuration
    ? setTimeout(() => stopSoundSample(name), config.maxDuration)
    : setTimeout(() => stopSoundSample(name), Math.max(250, (sample.duration || 3) * 1000));
  activeSoundSamples.set(name, { sample, timeout });
  return true;
}

function setSoundEnabled(enabled) {
  soundEnabled = Boolean(enabled);
  if (!soundEnabled) {
    stopAllSoundSamples();
    if (masterGain && audioContext) {
      const contextToClose = audioContext;
      masterGain.gain.cancelScheduledValues(contextToClose.currentTime);
      masterGain.gain.setValueAtTime(0, contextToClose.currentTime);
      audioContext = null;
      masterGain = null;
      noiseBuffer = null;
      contextToClose.close().catch(() => {});
    }
  }
  try {
    localStorage.setItem('battleSoundEnabled', String(soundEnabled));
  } catch (_) {
    // Some browsers disable storage for file URLs; sound still works for this session.
  }
  updateSoundToggle();
}

function applyMasterVolume() {
  if (masterGain && audioContext) {
    masterGain.gain.cancelScheduledValues(audioContext.currentTime);
    masterGain.gain.setValueAtTime(0.18 * masterVolume, audioContext.currentTime);
  }
  for (const [name, active] of activeSoundSamples) {
    const config = soundSamples[name];
    if (active?.sample && config) active.sample.volume = Math.max(0, Math.min(1, config.volume * masterVolume));
  }
}

function setMasterVolume(value) {
  masterVolume = Math.max(0, Math.min(1, Number(value) || 0));
  soundEnabled = masterVolume > 0;
  if (!soundEnabled) stopAllSoundSamples();
  applyMasterVolume();
  try {
    localStorage.setItem('battleMasterVolume', String(masterVolume));
    localStorage.setItem('battleSoundEnabled', String(soundEnabled));
  } catch (_) {
    // Some browsers disable storage for file URLs; volume still works for this session.
  }
  updateSoundToggle();
  updateVolumeUI();
}

function ensureAudio() {
  if (!soundEnabled) return null;
  const AudioContextClass = window.AudioContext || window.webkitAudioContext;
  if (!AudioContextClass) return null;
  if (!audioContext) {
    audioContext = new AudioContextClass();
    masterGain = audioContext.createGain();
    masterGain.gain.value = 0.18 * masterVolume;
    masterGain.connect(audioContext.destination);
    noiseBuffer = audioContext.createBuffer(1, audioContext.sampleRate, audioContext.sampleRate);
    const samples = noiseBuffer.getChannelData(0);
    for (let i = 0; i < samples.length; i += 1) samples[i] = Math.random() * 2 - 1;
  }
  if (audioContext.state === 'suspended') audioContext.resume();
  return audioContext;
}

function soundTone(frequency, duration, options = {}) {
  const ac = ensureAudio();
  if (!ac || !masterGain) return;
  const start = ac.currentTime + (options.delay || 0);
  const oscillator = ac.createOscillator();
  const gain = ac.createGain();
  oscillator.type = options.type || 'sine';
  oscillator.frequency.setValueAtTime(Math.max(20, frequency), start);
  if (options.endFrequency) {
    oscillator.frequency.exponentialRampToValueAtTime(Math.max(20, options.endFrequency), start + duration);
  }
  gain.gain.setValueAtTime(0.0001, start);
  gain.gain.exponentialRampToValueAtTime(options.volume || 0.32, start + Math.min(0.015, duration / 3));
  gain.gain.exponentialRampToValueAtTime(0.0001, start + duration);
  oscillator.connect(gain);
  gain.connect(masterGain);
  oscillator.start(start);
  oscillator.stop(start + duration + 0.02);
}

function soundOrchestralTone(frequency, duration, options = {}) {
  const ac = ensureAudio();
  if (!ac || !masterGain) return;
  const start = ac.currentTime + (options.delay || 0);
  const attack = Math.min(options.attack || 0.08, duration * 0.35);
  const release = Math.min(options.release || 0.24, duration * 0.45);
  const filter = ac.createBiquadFilter();
  const gain = ac.createGain();
  filter.type = 'lowpass';
  filter.frequency.value = options.brightness || 1250;
  filter.Q.value = 0.7;
  gain.gain.setValueAtTime(0.0001, start);
  gain.gain.exponentialRampToValueAtTime(options.volume || 0.2, start + attack);
  gain.gain.setValueAtTime(options.volume || 0.2, start + duration - release);
  gain.gain.exponentialRampToValueAtTime(0.0001, start + duration);
  filter.connect(gain);
  gain.connect(masterGain);
  [-7, 0, 7].forEach((detune, index) => {
    const oscillator = ac.createOscillator();
    oscillator.type = index === 1 ? 'sawtooth' : 'triangle';
    oscillator.frequency.value = Math.max(20, frequency);
    oscillator.detune.value = detune;
    oscillator.connect(filter);
    oscillator.start(start);
    oscillator.stop(start + duration + 0.02);
  });
}

function soundNoise(duration, options = {}) {
  const ac = ensureAudio();
  if (!ac || !masterGain || !noiseBuffer) return;
  const start = ac.currentTime + (options.delay || 0);
  const source = ac.createBufferSource();
  const filter = ac.createBiquadFilter();
  const gain = ac.createGain();
  source.buffer = noiseBuffer;
  filter.type = options.filterType || 'bandpass';
  filter.frequency.value = options.frequency || 700;
  filter.Q.value = options.q || 0.8;
  gain.gain.setValueAtTime(options.volume || 0.2, start);
  gain.gain.exponentialRampToValueAtTime(0.0001, start + duration);
  source.connect(filter);
  filter.connect(gain);
  gain.connect(masterGain);
  source.start(start);
  source.stop(start + duration);
}

function soundWhoosh(duration, options = {}) {
  const ac = ensureAudio();
  if (!ac || !masterGain || !noiseBuffer) return;
  const start = ac.currentTime + (options.delay || 0);
  const source = ac.createBufferSource();
  const filter = ac.createBiquadFilter();
  const gain = ac.createGain();
  source.buffer = noiseBuffer;
  filter.type = 'bandpass';
  filter.Q.value = options.q || 0.7;
  filter.frequency.setValueAtTime(options.startFrequency || 320, start);
  filter.frequency.exponentialRampToValueAtTime(options.peakFrequency || 1550, start + duration * 0.55);
  filter.frequency.exponentialRampToValueAtTime(options.endFrequency || 460, start + duration);
  gain.gain.setValueAtTime(0.0001, start);
  gain.gain.exponentialRampToValueAtTime(options.volume || 0.38, start + duration * 0.42);
  gain.gain.exponentialRampToValueAtTime(0.0001, start + duration);
  source.connect(filter);
  filter.connect(gain);
  gain.connect(masterGain);
  source.start(start);
  source.stop(start + duration);
}

function startRoyalChargeWind(fighter) {
  // Charge is intentionally silent; the visual wind streaks still show when ready.
}

function stopRoyalChargeWind(fighter) {
  const wind = fighter?.royalChargeWind;
  if (!wind) return;
  for (const layer of wind.layers || []) {
    try {
      layer.source.stop();
    } catch (_) {
      // The source may already have ended while the audio context was closing.
    }
    layer.source.disconnect();
    layer.filter.disconnect();
    layer.gain.disconnect();
  }
  try {
    wind.lfo?.stop();
  } catch (_) {
    // The oscillator may already have ended while the audio context was closing.
  }
  try {
    wind.howl?.stop();
    wind.howlLfo?.stop();
  } catch (_) {
    // These oscillators may already have ended while the audio context was closing.
  }
  wind.lfo?.disconnect();
  wind.lfoGain?.disconnect();
  wind.howl?.disconnect();
  wind.howlGain?.disconnect();
  wind.howlLfo?.disconnect();
  wind.howlDepth?.disconnect();
  wind.gain.disconnect();
  fighter.royalChargeWind = null;
  activeRoyalChargeWinds.delete(fighter);
}

function playSound(name, minInterval = 0) {
  if (suppressHiddenRoomAudio) return;
  if (!soundEnabled) return;
  const now = performance.now();
  if (now - (soundLastPlayed.get(name) || 0) < minInterval) return;
  soundLastPlayed.set(name, now);

  switch (name) {
    case 'ui':
      soundTone(620, 0.055, { type: 'square', volume: 0.12, endFrequency: 820 });
      break;
    case 'round':
      soundTone(140, 0.22, { type: 'sawtooth', volume: 0.25, endFrequency: 210 });
      soundTone(420, 0.2, { delay: 0.1, volume: 0.18, endFrequency: 620 });
      break;
    case 'swing':
      soundNoise(0.13, { frequency: 900, volume: 0.22 });
      soundTone(240, 0.12, { type: 'sawtooth', volume: 0.13, endFrequency: 90 });
      break;
    case 'swordSwing':
      soundWhoosh(0.28, { startFrequency: 260, peakFrequency: 1450, endFrequency: 380, q: 0.6, volume: 0.42 });
      break;
    case 'swordCrit':
      soundNoise(0.16, { filterType: 'lowpass', frequency: 300, q: 0.55, volume: 0.72 });
      soundTone(82, 0.24, { type: 'sawtooth', volume: 0.62, endFrequency: 30 });
      soundTone(185, 0.13, { type: 'square', volume: 0.3, endFrequency: 58 });
      break;
    case 'spiritStrike':
      soundNoise(0.15, { frequency: 1700, volume: 0.18 });
      soundTone(760, 0.15, { volume: 0.18, endFrequency: 300 });
      break;
    case 'rifle':
      soundNoise(0.11, { filterType: 'highpass', frequency: 1100, volume: 0.5 });
      soundTone(130, 0.13, { type: 'square', volume: 0.32, endFrequency: 60 });
      break;
    case 'silencedPistol':
      soundNoise(0.06, { filterType: 'bandpass', frequency: 850, q: 0.95, volume: 0.48 });
      soundNoise(0.035, { filterType: 'lowpass', frequency: 360, q: 0.5, volume: 0.38 });
      soundTone(118, 0.055, { type: 'triangle', volume: 0.28, endFrequency: 78 });
      break;
    case 'sniper':
      playSoundSample('sniper');
      soundNoise(0.07, { filterType: 'highpass', frequency: 2500, q: 0.35, volume: 0.34 });
      soundNoise(0.24, { filterType: 'lowpass', frequency: 470, q: 0.42, volume: 0.24 });
      soundTone(95, 0.26, { type: 'sawtooth', volume: 0.2, endFrequency: 32 });
      break;
    case 'sniperAbility':
      playSoundSample('sniperAbility');
      soundNoise(0.09, { filterType: 'highpass', frequency: 2300, q: 0.35, volume: 0.42 });
      soundNoise(0.42, { filterType: 'lowpass', frequency: 360, q: 0.4, volume: 0.36 });
      soundTone(72, 0.46, { type: 'sawtooth', volume: 0.3, endFrequency: 24 });
      soundTone(150, 0.22, { delay: 0.025, type: 'triangle', volume: 0.18, endFrequency: 42 });
      break;
    case 'crossbow':
      soundTone(210, 0.17, { type: 'triangle', volume: 0.28, endFrequency: 510 });
      soundNoise(0.14, { frequency: 950, volume: 0.16 });
      break;
    case 'royalArrow':
      // Tight bowstring snap followed by the arrow cutting through the air.
      soundTone(185, 0.075, { type: 'triangle', volume: 0.42, endFrequency: 920 });
      soundTone(860, 0.1, { type: 'sine', volume: 0.2, endFrequency: 310 });
      soundNoise(0.065, { filterType: 'highpass', frequency: 2100, q: 0.55, volume: 0.3 });
      soundWhoosh(0.2, {
        delay: 0.025,
        startFrequency: 1450,
        peakFrequency: 2350,
        endFrequency: 760,
        q: 0.7,
        volume: 0.2,
      });
      // Louder flame ignition and sustained fiery rush around the arrow.
      soundNoise(0.34, { delay: 0.015, filterType: 'lowpass', frequency: 1250, q: 0.38, volume: 0.48 });
      soundNoise(0.24, { delay: 0.04, filterType: 'bandpass', frequency: 1850, q: 0.65, volume: 0.34 });
      soundTone(145, 0.28, { delay: 0.025, type: 'sawtooth', volume: 0.18, endFrequency: 240 });
      break;
    case 'royalCharge':
      // Armored hoofbeats mark the transition; the wind itself loops while charged.
      [0, 0.12, 0.23].forEach((delay, index) => {
        soundNoise(0.11, {
          delay,
          filterType: 'lowpass',
          frequency: 330 - index * 35,
          q: 0.45,
          volume: 0.38 + index * 0.05,
        });
        soundTone(82 - index * 7, 0.13, {
          delay,
          type: 'triangle',
          volume: 0.28,
          endFrequency: 42,
        });
      });
      break;
    case 'bowDraw':
      playSoundSample('bowDraw');
      break;
    case 'fireball':
      soundNoise(0.26, { filterType: 'lowpass', frequency: 1100, volume: 0.25 });
      soundTone(180, 0.24, { type: 'sawtooth', volume: 0.17, endFrequency: 390 });
      break;
    case 'fireballImpact':
      soundNoise(0.3, { filterType: 'lowpass', frequency: 850, q: 0.5, volume: 0.42 });
      soundTone(125, 0.28, { type: 'sawtooth', volume: 0.3, endFrequency: 42 });
      break;
    case 'cosmicCast':
      soundNoise(0.72, { filterType: 'lowpass', frequency: 520, q: 0.8, volume: 0.34 });
      soundTone(118, 0.72, { type: 'sawtooth', volume: 0.28, endFrequency: 38 });
      soundTone(62, 0.85, { delay: 0.04, type: 'sine', volume: 0.24, endFrequency: 28 });
      break;
    case 'cloneSpawn':
      soundNoise(0.3, { filterType: 'bandpass', frequency: 480, q: 0.65, volume: 0.24 });
      soundTone(135, 0.32, { type: 'triangle', volume: 0.22, endFrequency: 52 });
      break;
    case 'cloneStrike':
      soundNoise(0.1, { filterType: 'bandpass', frequency: 720, q: 0.8, volume: 0.28 });
      soundTone(155, 0.14, { type: 'square', volume: 0.18, endFrequency: 68 });
      break;
    case 'iceStorm':
      soundNoise(0.42, { filterType: 'highpass', frequency: 2400, q: 0.7, volume: 0.24 });
      soundTone(1250, 0.38, { type: 'sine', volume: 0.13, endFrequency: 580 });
      break;
    case 'infernoBeam':
      soundNoise(0.58, { filterType: 'lowpass', frequency: 1450, q: 0.4, volume: 0.38 });
      soundTone(105, 0.5, { type: 'sawtooth', volume: 0.24, endFrequency: 210 });
      break;
    case 'blackHole':
      soundTone(82, 0.8, { type: 'sine', volume: 0.32, endFrequency: 28 });
      soundTone(164, 0.65, { type: 'triangle', volume: 0.15, endFrequency: 46 });
      soundNoise(0.65, { filterType: 'lowpass', frequency: 260, q: 1.2, volume: 0.2 });
      break;
    case 'meteor':
      soundWhoosh(0.38, { startFrequency: 360, peakFrequency: 1100, endFrequency: 190, q: 0.55, volume: 0.28 });
      break;
    case 'meteorImpact':
      soundNoise(0.42, { filterType: 'lowpass', frequency: 520, q: 0.45, volume: 0.52 });
      soundTone(72, 0.4, { type: 'sawtooth', volume: 0.4, endFrequency: 25 });
      break;
    case 'starDust':
      soundNoise(0.14, { filterType: 'lowpass', frequency: 480, q: 0.35, volume: 0.48 });
      soundNoise(0.035, { filterType: 'bandpass', frequency: 820, q: 0.3, volume: 0.3 });
      break;
    case 'lightning':
      soundNoise(0.12, { filterType: 'highpass', frequency: 3200, q: 0.35, volume: 0.44 });
      soundTone(105, 0.22, { type: 'square', volume: 0.25, endFrequency: 38 });
      break;
    case 'lightningZone':
      soundTone(310, 0.48, { type: 'sawtooth', volume: 0.16, endFrequency: 720 });
      soundNoise(0.38, { filterType: 'highpass', frequency: 2600, q: 0.75, volume: 0.18 });
      break;
    case 'hit':
      soundNoise(0.075, { filterType: 'lowpass', frequency: 520, volume: 0.3 });
      soundTone(95, 0.09, { type: 'triangle', volume: 0.25, endFrequency: 55 });
      break;
    case 'block':
      soundTone(980, 0.13, { type: 'square', volume: 0.23, endFrequency: 640 });
      soundTone(1450, 0.08, { delay: 0.025, volume: 0.16 });
      break;
    case 'explosion':
      soundNoise(0.42, { filterType: 'lowpass', frequency: 680, volume: 0.24 });
      soundTone(85, 0.38, { type: 'sawtooth', volume: 0.2, endFrequency: 32 });
      break;
    case 'banditBomb':
      playSoundSample('banditBomb');
      soundNoise(0.34, { filterType: 'lowpass', frequency: 640, q: 0.45, volume: 0.2 });
      soundTone(80, 0.3, { type: 'sawtooth', volume: 0.17, endFrequency: 30 });
      break;
    case 'infantryGrenade':
      playSoundSample('infantryGrenade');
      soundNoise(0.4, { filterType: 'lowpass', frequency: 520, q: 0.42, volume: 0.24 });
      soundNoise(0.08, { filterType: 'highpass', frequency: 1700, q: 0.35, volume: 0.13 });
      soundTone(68, 0.38, { type: 'sawtooth', volume: 0.2, endFrequency: 24 });
      break;
    case 'teleport':
      soundTone(260, 0.2, { volume: 0.2, endFrequency: 1250 });
      soundTone(1150, 0.16, { delay: 0.08, type: 'triangle', volume: 0.15, endFrequency: 390 });
      break;
    case 'trap':
      soundTone(720, 0.075, { type: 'square', volume: 0.2, endFrequency: 280 });
      soundTone(340, 0.09, { delay: 0.06, type: 'square', volume: 0.16 });
      break;
    case 'splash':
      soundNoise(0.22, { filterType: 'lowpass', frequency: 760, q: 0.5, volume: 0.34 });
      soundNoise(0.12, { delay: 0.04, filterType: 'bandpass', frequency: 1250, q: 0.65, volume: 0.18 });
      break;
    case 'magic':
      [330, 495, 740].forEach((frequency, index) => soundTone(frequency, 0.18, { delay: index * 0.055, volume: 0.15, endFrequency: frequency * 1.3 }));
      break;
    case 'dash':
      soundWhoosh(0.32, {
        startFrequency: 240,
        peakFrequency: 1900,
        endFrequency: 520,
        q: 0.48,
        volume: 0.52,
      });
      break;
    case 'lifeSteal':
      soundTone(680, 0.35, { type: 'sine', volume: 0.2, endFrequency: 120 });
      soundTone(920, 0.24, { delay: 0.04, volume: 0.1, endFrequency: 250 });
      break;
    case 'summon':
      // Dark orchestral soul-summoning sting in D minor.
      [36.7, 55, 73.4].forEach((frequency, index) => {
        soundOrchestralTone(frequency, 3.25, {
          volume: index === 0 ? 0.34 : 0.22,
          attack: 0.16,
          release: 0.55,
          brightness: 620,
        });
      });
      [
        [146.8, 0.05, 0.72],
        [174.6, 0.58, 0.68],
        [164.8, 1.08, 0.7],
        [130.8, 1.58, 0.76],
        [110, 2.12, 1.05],
      ].forEach(([frequency, delay, duration]) => {
        soundOrchestralTone(frequency, duration, {
          delay,
          volume: 0.3,
          attack: 0.065,
          release: 0.22,
          brightness: 1500,
        });
      });
      [110, 130.8, 164.8, 220].forEach((frequency, index) => {
        soundOrchestralTone(frequency, 1.05, {
          delay: 2.18,
          volume: index === 0 ? 0.32 : 0.2,
          attack: 0.08,
          release: 0.5,
          brightness: 1750,
        });
      });
      soundNoise(0.32, { filterType: 'lowpass', frequency: 180, q: 0.5, volume: 0.55 });
      soundNoise(0.38, { delay: 2.15, filterType: 'lowpass', frequency: 220, q: 0.5, volume: 0.48 });
      break;
    case 'horse':
      soundTone(72, 0.16, { type: 'triangle', volume: 0.34, endFrequency: 48 });
      soundNoise(0.1, { filterType: 'lowpass', frequency: 380, volume: 0.2 });
      break;
    case 'dismount':
      soundNoise(0.3, { filterType: 'lowpass', frequency: 430, volume: 0.48 });
      soundTone(65, 0.3, { type: 'sawtooth', volume: 0.37, endFrequency: 30 });
      break;
    case 'reload':
      soundTone(1100, 0.045, { type: 'square', volume: 0.13, endFrequency: 600 });
      soundTone(750, 0.06, { delay: 0.11, type: 'square', volume: 0.14, endFrequency: 1150 });
      break;
    case 'throw':
      soundNoise(0.18, { frequency: 1050, volume: 0.15 });
      soundTone(260, 0.16, { volume: 0.12, endFrequency: 120 });
      break;
    case 'victory':
      [392, 523, 659, 784].forEach((frequency, index) => soundTone(frequency, 0.28, { delay: index * 0.11, type: 'triangle', volume: 0.22 }));
      break;
    case 'tournamentVictory': {
      const melody = [
        [392, 0, 0.3],
        [523, 0.28, 0.3],
        [659, 0.56, 0.38],
        [784, 0.92, 0.32],
        [659, 1.22, 0.25],
        [784, 1.5, 0.34],
        [1047, 1.84, 0.85],
      ];
      melody.forEach(([frequency, delay, duration]) => {
        soundTone(frequency, duration, { delay, type: 'triangle', volume: 0.24 });
        soundTone(frequency / 2, duration, { delay, type: 'sine', volume: 0.11 });
      });
      [262, 330, 392].forEach((frequency) => {
        soundTone(frequency, 1.05, { delay: 1.84, type: 'sine', volume: 0.13 });
      });
      break;
    }
    default:
      break;
  }
}

function updateSoundToggle() {
  if (!soundToggleButton) return;
  soundToggleButton.textContent = soundEnabled ? 'Sound: On' : 'Sound: Off';
  soundToggleButton.setAttribute('aria-pressed', soundEnabled ? 'false' : 'true');
}

function updateVolumeUI() {
  if (volumeSlider) volumeSlider.value = String(Math.round(masterVolume * 100));
  if (volumeMenuButton) {
    volumeMenuButton.textContent = masterVolume <= 0 ? '🔇' : masterVolume < 0.45 ? '🔉' : '🔊';
    volumeMenuButton.setAttribute('aria-label', `Volume ${Math.round(masterVolume * 100)}%`);
    volumeMenuButton.title = `Volume ${Math.round(masterVolume * 100)}%`;
  }
}

function setRestartButtonMode(label = 'Restart') {
  if (!restartButton) return;
  const isExitAction = /return|exit/i.test(label);
  restartButton.dataset.actionLabel = label;
  restartButton.setAttribute('aria-label', label);
  restartButton.title = label;
  restartButton.classList.toggle('is-exit-door', isExitAction);
  restartButton.textContent = /next/i.test(label) ? '➜' : isExitAction ? '🚪' : '↻';
}

function ensureInMatchExitButtonMode() {
  if (!restartButton || restartButton.dataset.actionLabel !== 'Restart') return;
  const label = tournamentMode
    ? 'Exit Tournament'
    : bossMode
      ? 'Exit Boss Fight'
      : tutorialMode
        ? 'Exit Tutorial'
        : aiDuelMode
          ? 'Exit AI Duel'
          : 'Exit Match';
  setRestartButtonMode(label);
}

function setPaused(paused) {
  gamePaused = Boolean(paused);
  if (gamePaused) resetInputKeys();
  pauseButton?.setAttribute('aria-pressed', gamePaused ? 'true' : 'false');
  if (pauseButton) {
    pauseButton.classList.toggle('is-resume-icon', gamePaused);
    pauseButton.textContent = gamePaused ? '▶' : '⏸';
    pauseButton.setAttribute('aria-label', gamePaused ? 'Resume' : 'Pause');
    pauseButton.title = gamePaused ? 'Resume' : 'Pause';
  }
}

function togglePauseMenu(forceOpen = null) {
  const shouldOpen = forceOpen === null ? pauseMenu?.classList.contains('hidden') : Boolean(forceOpen);
  pauseMenu?.classList.toggle('hidden', !shouldOpen);
  pauseButton?.setAttribute('aria-expanded', shouldOpen ? 'true' : 'false');
  if (!shouldOpen) {
    volumePanel?.classList.add('hidden');
    volumeMenuButton?.setAttribute('aria-expanded', 'false');
  }
}

function setGameControlsInMatch(inMatch) {
  gameShell?.classList.toggle('in-match', Boolean(inMatch));
  if (!inMatch) {
    setPaused(false);
    pauseMenu?.classList.add('hidden');
    pauseButton?.setAttribute('aria-expanded', 'false');
  }
}
