function isRiverMap() {
  return activeMap === 'river';
}

function isForestMap() {
  return activeMap === 'forest';
}

function isCityMap() {
  return activeMap === 'city';
}

function isOceanMap() {
  return activeMap === 'ocean';
}

function isVolcanoMap() {
  return activeMap === 'volcano';
}

function isLargeMap() {
  return isRiverMap() || isForestMap() || isCityMap() || isOceanMap() || isVolcanoMap();
}

function getWorldWidth() {
  if (isRiverMap()) return RIVER_WORLD_WIDTH;
  if (isForestMap()) return FOREST_WORLD_WIDTH;
  if (isCityMap()) return CITY_WORLD_WIDTH;
  if (isOceanMap()) return OCEAN_WORLD_WIDTH;
  if (isVolcanoMap()) return VOLCANO_WORLD_WIDTH;
  return GAME_WIDTH;
}

function getWorldHeight() {
  if (isRiverMap()) return RIVER_WORLD_HEIGHT;
  if (isForestMap()) return FOREST_WORLD_HEIGHT;
  if (isCityMap()) return CITY_WORLD_HEIGHT;
  if (isOceanMap()) return OCEAN_WORLD_HEIGHT;
  if (isVolcanoMap()) return VOLCANO_WORLD_HEIGHT;
  return GAME_HEIGHT;
}

function getGroundY() {
  if (isRiverMap()) return RIVER_GROUND_Y;
  if (isForestMap()) return FOREST_GROUND_Y;
  if (isCityMap()) return CITY_GROUND_Y;
  if (isOceanMap()) return OCEAN_GROUND_Y;
  if (isVolcanoMap()) return VOLCANO_GROUND_Y;
  return groundY;
}

function getRiverSurfaceY() {
  return isRiverMap() ? RIVER_SURFACE_Y : groundY + 10;
}

function getSniperAimMaxY() {
  return (isRiverMap() || isOceanMap()) ? getWorldHeight() - 8 : getGroundY() - 8;
}

function getTargetPredictionMaxY(target) {
  return (isRiverMap() || isOceanMap()) ? getWorldHeight() - target.height / 2 : getGroundY() - target.height / 2;
}

function getSelectedMapType() {
  if (mapSelect?.value === 'river') return 'river';
  if (mapSelect?.value === 'forest') return 'forest';
  if (mapSelect?.value === 'city') return 'city';
  if (mapSelect?.value === 'ocean') return 'ocean';
  if (mapSelect?.value === 'volcano') return 'volcano';
  return 'random';
}

function withMapPreviewTransform(worldWidth, worldHeight, drawPreview) {
  if (!mapPreviewCtx || !mapPreviewCanvas) return;
  const previewWidth = mapPreviewCanvas.width;
  const previewHeight = mapPreviewCanvas.height;
  const scale = Math.min(previewWidth / worldWidth, previewHeight / worldHeight);
  const offsetX = (previewWidth - worldWidth * scale) / 2;
  const offsetY = (previewHeight - worldHeight * scale) / 2;
  mapPreviewCtx.save();
  mapPreviewCtx.clearRect(0, 0, previewWidth, previewHeight);
  mapPreviewCtx.fillStyle = '#101821';
  mapPreviewCtx.fillRect(0, 0, previewWidth, previewHeight);
  mapPreviewCtx.translate(offsetX, offsetY);
  mapPreviewCtx.scale(scale, scale);
  drawPreview(mapPreviewCtx);
  mapPreviewCtx.restore();
}

function drawPreviewPlatform(previewCtx, platform) {
  previewCtx.fillStyle = '#3d4f5f';
  previewCtx.fillRect(platform.x, platform.y, platform.width, platform.height);
  previewCtx.fillStyle = platform.moving ? '#8fb4c7' : '#5d7d94';
  previewCtx.fillRect(platform.x, platform.y, platform.width, 4);
  if (platform.moving) {
    previewCtx.fillStyle = 'rgba(255, 255, 255, 0.28)';
    previewCtx.fillRect(platform.x + 10, platform.y + platform.height - 4, platform.width - 20, 2);
  }
}

