function getCityFallDamageRange() {
  const heights = getCityBuildingBlueprints().map((building) => building.height);
  return {
    min: Math.min(...heights),
    max: Math.max(...heights),
  };
}

function getCityFallLegDamage(fallDistance) {
  const { min, max } = getCityFallDamageRange();
  const t = max === min ? 1 : clamp((fallDistance - min) / (max - min), 0, 1);
  return Math.round(CITY_MIN_FALL_LEG_DAMAGE + (CITY_MAX_FALL_LEG_DAMAGE - CITY_MIN_FALL_LEG_DAMAGE) * t);
}

