function getOceanIsland() {
  const centerX = OCEAN_WORLD_WIDTH / 2;
  const topY = OCEAN_WATER_SURFACE_Y - 34;
  return {
    x: centerX - OCEAN_ISLAND_WIDTH / 2,
    y: topY,
    width: OCEAN_ISLAND_WIDTH,
    height: OCEAN_ISLAND_HEIGHT,
    topY,
  };
}

function isOnOceanIsland(player) {
  if (!isOceanMap() || !player || player.dead) return false;
  const island = getOceanIsland();
  const bottom = player.y + player.height;
  return (
    Math.abs(bottom - island.topY) <= 4 &&
    player.x + player.width > island.x + 8 &&
    player.x < island.x + island.width - 8
  );
}

function canBoardOceanIsland(player) {
  if (!isOceanMap() || !player || player.dead) return false;
  const island = getOceanIsland();
  const centerX = player.x + player.width / 2;
  const bottom = player.y + player.height;
  const mountedPrinceAllowance = player.characterTypeKey === 'royalPrince' && player.isMounted ? 38 : 0;
  return (
    centerX > island.x + 8 &&
    centerX < island.x + island.width - 8 &&
    bottom >= island.topY - 28 - mountedPrinceAllowance &&
    bottom <= OCEAN_WATER_SURFACE_Y + 76 + mountedPrinceAllowance
  );
}

function shouldSeekOceanIsland(player) {
  if (!isOceanMap() || !player || player.dead || isOnOceanIsland(player)) return false;
  const liveParts = Object.values(player.parts || {}).filter((part) => part && part.cur > 0);
  if (!liveParts.length) return false;
  const totalCur = liveParts.reduce((sum, part) => sum + part.cur, 0);
  const totalMax = liveParts.reduce((sum, part) => sum + part.max, 0);
  return totalMax > 0 && totalCur / totalMax <= 0.38;
}

function isUnderwaterEntity(entity) {
  return isOceanMap() && entity && entity.y + (entity.height || 0) / 2 > OCEAN_WATER_SURFACE_Y;
}

function drawPreviewOceanMap(previewCtx) {
  const skyGradient = previewCtx.createLinearGradient(0, 0, 0, OCEAN_WATER_SURFACE_Y);
  skyGradient.addColorStop(0, '#86c5e8');
  skyGradient.addColorStop(1, '#d8f0ff');
  previewCtx.fillStyle = skyGradient;
  previewCtx.fillRect(0, 0, OCEAN_WORLD_WIDTH, OCEAN_WATER_SURFACE_Y);

  const waterGradient = previewCtx.createLinearGradient(0, OCEAN_WATER_SURFACE_Y, 0, OCEAN_WORLD_HEIGHT);
  waterGradient.addColorStop(0, '#2085b5');
  waterGradient.addColorStop(0.45, '#0d4d78');
  waterGradient.addColorStop(1, '#051a30');
  previewCtx.fillStyle = waterGradient;
  previewCtx.fillRect(0, OCEAN_WATER_SURFACE_Y, OCEAN_WORLD_WIDTH, OCEAN_WORLD_HEIGHT - OCEAN_WATER_SURFACE_Y);

  previewCtx.strokeStyle = 'rgba(210, 245, 255, 0.48)';
  previewCtx.lineWidth = 4;
  previewCtx.beginPath();
  previewCtx.moveTo(0, OCEAN_WATER_SURFACE_Y + 4);
  for (let x = 0; x <= OCEAN_WORLD_WIDTH; x += 80) {
    previewCtx.lineTo(x, OCEAN_WATER_SURFACE_Y + Math.sin(x * 0.025) * 8);
  }
  previewCtx.stroke();

  const island = getOceanIsland();
  previewCtx.fillStyle = '#d6b16b';
  previewCtx.beginPath();
  previewCtx.ellipse(island.x + island.width / 2, island.topY + 24, island.width / 2, 48, 0, 0, Math.PI * 2);
  previewCtx.fill();
  previewCtx.fillStyle = '#4c8f45';
  previewCtx.beginPath();
  previewCtx.ellipse(island.x + island.width / 2, island.topY + 2, island.width * 0.38, 20, 0, 0, Math.PI * 2);
  previewCtx.fill();

  previewCtx.fillStyle = 'rgba(255, 255, 255, 0.28)';
  for (let i = 0; i < 9; i++) {
    previewCtx.beginPath();
    previewCtx.arc(220 + i * 170, OCEAN_WATER_SURFACE_Y + 120 + (i % 3) * 80, 8, 0, Math.PI * 2);
    previewCtx.fill();
  }

  drawOceanSeabed(previewCtx, OCEAN_WORLD_WIDTH, OCEAN_WORLD_HEIGHT, false);
}

function drawOceanSeabed(drawCtx, worldWidth, worldHeight, animated = true) {
  const bedTop = OCEAN_BOTTOM_LIMIT_Y;
  const time = animated ? Date.now() * 0.0015 : 0;
  const sandGradient = drawCtx.createLinearGradient(0, bedTop, 0, worldHeight);
  sandGradient.addColorStop(0, 'rgba(155, 125, 82, 0.82)');
  sandGradient.addColorStop(0.45, 'rgba(101, 80, 61, 0.92)');
  sandGradient.addColorStop(1, 'rgba(35, 36, 46, 0.96)');
  drawCtx.fillStyle = sandGradient;
  drawCtx.beginPath();
  drawCtx.moveTo(0, worldHeight);
  drawCtx.lineTo(0, bedTop + 12);
  for (let x = 0; x <= worldWidth; x += 42) {
    const y = bedTop + Math.sin(x * 0.013) * 15 + Math.sin(x * 0.047) * 6;
    drawCtx.lineTo(x, y);
  }
  drawCtx.lineTo(worldWidth, worldHeight);
  drawCtx.closePath();
  drawCtx.fill();

  drawCtx.save();
  drawCtx.globalAlpha = 0.92;
  for (let i = 0; i < 18; i++) {
    const x = 70 + i * 118;
    const baseY = bedTop + 24 + Math.sin(i * 1.7) * 13;
    const radius = 18 + (i % 4) * 7;
    drawCtx.fillStyle = i % 3 === 0 ? '#28333d' : i % 3 === 1 ? '#3a3f45' : '#262a33';
    drawCtx.beginPath();
    drawCtx.ellipse(x, baseY + radius * 0.36, radius * 1.3, radius * 0.62, Math.sin(i) * 0.35, 0, Math.PI * 2);
    drawCtx.fill();
    drawCtx.fillStyle = 'rgba(130, 154, 159, 0.16)';
    drawCtx.beginPath();
    drawCtx.ellipse(x - radius * 0.26, baseY + radius * 0.1, radius * 0.38, radius * 0.18, -0.35, 0, Math.PI * 2);
    drawCtx.fill();
  }

  drawCtx.strokeStyle = 'rgba(77, 139, 106, 0.65)';
  drawCtx.lineWidth = 4;
  drawCtx.lineCap = 'round';
  for (let i = 0; i < 13; i++) {
    const x = 45 + i * 165;
    const baseY = bedTop + 20 + Math.sin(i * 2.1) * 10;
    const sway = Math.sin(time * 2 + i) * 7;
    drawCtx.beginPath();
    drawCtx.moveTo(x, baseY + 30);
    drawCtx.quadraticCurveTo(x + sway, baseY + 7, x + 5 + sway * 0.6, baseY - 24);
    drawCtx.stroke();
    drawCtx.beginPath();
    drawCtx.moveTo(x + 7, baseY + 29);
    drawCtx.quadraticCurveTo(x - 5 + sway, baseY + 12, x + 13 + sway, baseY - 12);
    drawCtx.stroke();
  }

  drawCtx.fillStyle = 'rgba(205, 185, 130, 0.42)';
  for (let i = 0; i < 80; i++) {
    const x = (i * 73) % worldWidth;
    const y = bedTop + 18 + ((i * 29) % 72);
    drawCtx.beginPath();
    drawCtx.arc(x, y, 1.5 + (i % 3) * 0.8, 0, Math.PI * 2);
    drawCtx.fill();
  }
  drawCtx.restore();
}

function getVolcanoCraterLeft() {
  return VOLCANO_MOUNTAIN.x - VOLCANO_MOUNTAIN.craterWidth / 2;
}

function getVolcanoCraterRight() {
  return VOLCANO_MOUNTAIN.x + VOLCANO_MOUNTAIN.craterWidth / 2;
}

function getVolcanoSurfaceY(x) {
  const mountain = VOLCANO_MOUNTAIN;
  const leftBase = mountain.x - mountain.width / 2;
  const rightBase = mountain.x + mountain.width / 2;
  const craterLeft = getVolcanoCraterLeft();
  const craterRight = getVolcanoCraterRight();
  const rimY = mountain.baseY - mountain.height + 48;
  const craterLipWidth = 38;
  if (x < leftBase || x > rightBase) return null;
  if (x > craterLeft && x < craterRight) {
    const leftLipDepth = x - craterLeft;
    const rightLipDepth = craterRight - x;
    if (leftLipDepth <= craterLipWidth) return rimY + leftLipDepth * 0.28;
    if (rightLipDepth <= craterLipWidth) return rimY + rightLipDepth * 0.28;
    return null;
  }

  const sideStart = x <= craterLeft ? leftBase : craterRight;
  const sideEnd = x <= craterLeft ? craterLeft : rightBase;
  const rawT = clamp((x - sideStart) / (sideEnd - sideStart), 0, 1);
  const t = x <= craterLeft ? rawT : 1 - rawT;
  const eased = 1 - Math.pow(1 - t, 1.28);
  const jag = Math.sin(x * 0.024) * 11 + Math.sin(x * 0.061) * 4;
  return mountain.baseY - (mountain.baseY - rimY) * eased + jag;
}

function getVolcanoSurfaceForBox(box) {
  if (!isVolcanoMap()) return null;
  const sampleXs = [
    box.x,
    box.x + box.width * 0.25,
    box.x + box.width / 2,
    box.x + box.width * 0.75,
    box.x + box.width,
  ];
  let highestSurface = null;
  for (const sampleX of sampleXs) {
    const surfaceY = getVolcanoSurfaceY(sampleX);
    if (surfaceY === null) continue;
    if (highestSurface === null || surfaceY < highestSurface) highestSurface = surfaceY;
  }
  return highestSurface;
}

function doesBoxHitVolcanoTerrain(box) {
  const surfaceY = getVolcanoSurfaceForBox(box);
  if (surfaceY === null) return false;
  return box.y + box.height >= surfaceY;
}

function getSpawnSurfaceY(x) {
  if (isVolcanoMap()) return getVolcanoSurfaceY(x) ?? getGroundY();
  return getGroundY();
}

function drawPreviewVolcanoMap(previewCtx) {
  const floorY = VOLCANO_GROUND_Y;
  const worldWidth = VOLCANO_WORLD_WIDTH;
  const worldHeight = VOLCANO_WORLD_HEIGHT;
  const skyGradient = previewCtx.createLinearGradient(0, 0, 0, floorY);
  skyGradient.addColorStop(0, '#170812');
  skyGradient.addColorStop(0.55, '#42151b');
  skyGradient.addColorStop(1, '#7a2c18');
  previewCtx.fillStyle = skyGradient;
  previewCtx.fillRect(0, 0, worldWidth, worldHeight);

  previewCtx.fillStyle = 'rgba(255, 119, 36, 0.15)';
  previewCtx.beginPath();
  previewCtx.arc(worldWidth * 0.5, floorY - 360, 210, 0, Math.PI * 2);
  previewCtx.fill();

  previewCtx.fillStyle = '#23151a';
  for (let x = -70; x < worldWidth; x += 230) {
    previewCtx.beginPath();
    previewCtx.moveTo(x, floorY);
    previewCtx.lineTo(x + 125, floorY - 185);
    previewCtx.lineTo(x + 250, floorY);
    previewCtx.closePath();
    previewCtx.fill();
  }

  drawVolcanoMountain(previewCtx, false);
  drawPreviewVolcanoMagma(previewCtx);
}

function drawPreviewVolcanoMagma(previewCtx) {
  const mountain = VOLCANO_MOUNTAIN;
  const mouthY = mountain.baseY - mountain.height + 30;
  const shots = [
    { side: -1, landX: mountain.x - 390, arc: 190, river: 185 },
    { side: -1, landX: mountain.x - 235, arc: 145, river: 135 },
    { side: 1, landX: mountain.x + 285, arc: 165, river: 170 },
    { side: 1, landX: mountain.x + 455, arc: 215, river: 205 },
  ];

  previewCtx.save();
  previewCtx.globalCompositeOperation = 'lighter';
  previewCtx.lineCap = 'round';
  previewCtx.lineJoin = 'round';
  for (const shot of shots) {
    const startX = mountain.x + shot.side * randomPreviewOffset(shot.landX);
    const startY = mouthY;
    const landY = getVolcanoSurfaceY(shot.landX) ?? mountain.baseY;
    previewCtx.strokeStyle = 'rgba(255, 106, 30, 0.55)';
    previewCtx.lineWidth = 8;
    previewCtx.beginPath();
    previewCtx.moveTo(startX, startY);
    previewCtx.quadraticCurveTo(
      (startX + shot.landX) / 2,
      Math.min(startY, landY) - shot.arc,
      shot.landX,
      landY - 8
    );
    previewCtx.stroke();

    previewCtx.fillStyle = '#ffd166';
    previewCtx.beginPath();
    previewCtx.arc(shot.landX, landY - 8, 14, 0, Math.PI * 2);
    previewCtx.fill();

    const streamPoints = [];
    for (let i = 0; i <= 9; i++) {
      const x = shot.landX + shot.side * i * (shot.river / 9);
      const y = (getVolcanoSurfaceY(x) ?? landY) - 7 + Math.sin(i * 1.7) * 4;
      streamPoints.push({ x, y });
    }
    previewCtx.strokeStyle = 'rgba(255, 74, 24, 0.86)';
    previewCtx.lineWidth = 25;
    previewCtx.beginPath();
    for (let i = 0; i < streamPoints.length; i++) {
      const point = streamPoints[i];
      if (i === 0) previewCtx.moveTo(point.x, point.y);
      else {
        const prev = streamPoints[i - 1];
        previewCtx.quadraticCurveTo(prev.x, prev.y, (prev.x + point.x) / 2, (prev.y + point.y) / 2);
      }
    }
    previewCtx.stroke();

    previewCtx.strokeStyle = 'rgba(255, 218, 103, 0.78)';
    previewCtx.lineWidth = 8;
    previewCtx.stroke();
  }
  previewCtx.restore();
}

function randomPreviewOffset(value) {
  return Math.sin(value * 0.017) * 18;
}

function drawVolcanoMountain(drawCtx, animated = true) {
  const mountain = VOLCANO_MOUNTAIN;
  const topY = mountain.baseY - mountain.height;
  const mouthY = topY + 26;
  const time = animated ? Date.now() * 0.004 : 0;
  drawCtx.save();
  drawCtx.fillStyle = '#1b1115';
  drawCtx.beginPath();
  drawCtx.moveTo(mountain.x - mountain.width / 2, mountain.baseY);
  drawCtx.lineTo(mountain.x - 210, mountain.baseY - 120);
  drawCtx.lineTo(mountain.x - 160, mountain.baseY - 245);
  drawCtx.lineTo(mountain.x - 70, topY + 32);
  drawCtx.lineTo(mountain.x - mountain.craterWidth / 2, mouthY);
  drawCtx.lineTo(mountain.x + mountain.craterWidth / 2, mouthY);
  drawCtx.lineTo(mountain.x + 75, topY + 44);
  drawCtx.lineTo(mountain.x + 155, mountain.baseY - 230);
  drawCtx.lineTo(mountain.x + 225, mountain.baseY - 110);
  drawCtx.lineTo(mountain.x + mountain.width / 2, mountain.baseY);
  drawCtx.closePath();
  drawCtx.fill();

  const leftBase = mountain.x - mountain.width / 2;
  const rightBase = mountain.x + mountain.width / 2;
  const craterLeft = getVolcanoCraterLeft();
  const craterRight = getVolcanoCraterRight();
  const bottomY = mountain.baseY + 240;
  const drawVolcanoSide = (startX, endX) => {
    const direction = startX < endX ? 1 : -1;
    drawCtx.beginPath();
    drawCtx.moveTo(startX, bottomY);
    for (let x = startX; direction > 0 ? x <= endX : x >= endX; x += direction * 34) {
      drawCtx.lineTo(x, getVolcanoSurfaceY(x) ?? mountain.baseY);
    }
    drawCtx.lineTo(endX, getVolcanoSurfaceY(endX) ?? mountain.baseY);
    drawCtx.lineTo(endX, bottomY);
    drawCtx.closePath();
    drawCtx.fill();
  };

  drawCtx.fillStyle = '#211316';
  drawVolcanoSide(leftBase, craterLeft);
  drawVolcanoSide(rightBase, craterRight);

  drawCtx.strokeStyle = 'rgba(255, 128, 45, 0.45)';
  drawCtx.lineWidth = 4;
  for (const [startX, endX] of [[leftBase, craterLeft + 38], [craterRight - 38, rightBase]]) {
    drawCtx.beginPath();
    for (let x = startX; startX < endX ? x <= endX : x >= endX; x += (startX < endX ? 28 : -28)) {
      const y = getVolcanoSurfaceY(x);
      if (y === null) continue;
      if (x === startX) drawCtx.moveTo(x, y);
      else drawCtx.lineTo(x, y);
    }
    drawCtx.stroke();
  }

  drawCtx.fillStyle = '#2d1718';
  drawCtx.beginPath();
  drawCtx.moveTo(mountain.x - mountain.craterWidth / 2, mouthY);
  drawCtx.lineTo(mountain.x, mouthY + 36);
  drawCtx.lineTo(mountain.x + mountain.craterWidth / 2, mouthY);
  drawCtx.closePath();
  drawCtx.fill();

  drawCtx.strokeStyle = 'rgba(255, 92, 24, 0.72)';
  drawCtx.lineWidth = 6;
  const spillLines = [
    { x: -34, lean: -76, length: 315 },
    { x: 26, lean: 68, length: 285 },
    { x: 0, lean: 8, length: 370 },
  ];
  for (const spill of spillLines) {
    drawCtx.beginPath();
    drawCtx.moveTo(mountain.x + spill.x, mouthY + 8);
    drawCtx.quadraticCurveTo(
      mountain.x + spill.x + spill.lean * 0.35 + Math.sin(time + spill.x) * 8,
      mouthY + spill.length * 0.45,
      mountain.x + spill.x + spill.lean,
      mouthY + spill.length
    );
    drawCtx.stroke();
  }

  drawCtx.fillStyle = 'rgba(255, 178, 66, 0.9)';
  drawCtx.beginPath();
  drawCtx.ellipse(mountain.x, mouthY + 4, mountain.craterWidth / 2, 15, 0, 0, Math.PI * 2);
  drawCtx.fill();
  drawCtx.restore();
}

function drawMapPreview() {
  if (!mapPreviewCtx || !mapPreviewCanvas) return;
  const selectedMap = mapSelect?.value || 'classic';
  if (selectedMap === 'river') {
    withMapPreviewTransform(RIVER_WORLD_WIDTH, RIVER_WORLD_HEIGHT, drawPreviewRiverMap);
  } else if (selectedMap === 'forest') {
    withMapPreviewTransform(FOREST_WORLD_WIDTH, FOREST_WORLD_HEIGHT, drawPreviewForestMap);
  } else if (selectedMap === 'city') {
    withMapPreviewTransform(CITY_WORLD_WIDTH, CITY_WORLD_HEIGHT, drawPreviewCityMap);
  } else if (selectedMap === 'ocean') {
    withMapPreviewTransform(OCEAN_WORLD_WIDTH, OCEAN_WORLD_HEIGHT, drawPreviewOceanMap);
  } else if (selectedMap === 'volcano') {
    withMapPreviewTransform(VOLCANO_WORLD_WIDTH, VOLCANO_WORLD_HEIGHT, drawPreviewVolcanoMap);
  } else {
    withMapPreviewTransform(GAME_WIDTH, GAME_HEIGHT, drawPreviewClassicMap);
  }
}

function riverRightEdge() {
  return riverBounds.x + riverBounds.width;
}

function isPointInRiver(x) {
  return isRiverMap() && x >= riverBounds.x && x <= riverRightEdge();
}

function doesBoxTouchRiverWater(box) {
  if (!isRiverMap()) return false;
  const overlapsRiverX = box.x + box.width > riverBounds.x && box.x < riverRightEdge();
  const touchesWaterY = box.y + box.height >= getRiverSurfaceY();
  return overlapsRiverX && touchesWaterY;
}

function getCelestialRiverSurfaceHit(box, arrow) {
  if (!isRiverMap() || !arrow?.celestial) return null;
  if (doesBoxTouchRiverWater(box)) return { axis: 'y', y: getRiverSurfaceY() - box.height / 2 };
  if (box.y + box.height >= getGroundY()) return { axis: 'y', y: getGroundY() - box.height / 2 };
  for (const platform of getCollisionPlatforms()) {
    if (!rectIntersect(box, platform)) continue;
    const axis = Math.abs(arrow.velocityX || 0) > Math.abs(arrow.velocityY || 0) ? 'x' : 'y';
    return { axis };
  }
  return null;
}

function isFighterOnCityBuilding(player) {
  if (!isCityMap() || !player || player.dead) return false;
  return Boolean(player.climbingBuilding || player.cityRooftopJumping || getCityRooftopNearFighter(player));
}

function shouldCityCameraKeepRoadVisible() {
  return isCityMap() && !(isFighterOnCityBuilding(player1) && isFighterOnCityBuilding(player2));
}

function getCityRooftopNearFighter(player) {
  if (!isCityMap() || !player) return null;
  const bottom = player.y + player.height;
  return cityBuildings.find((building) => (
    bottom >= building.roofY - 120 &&
    bottom <= building.roofY + 46 &&
    player.x + player.width > building.x - 10 &&
    player.x < building.x + building.width + 10
  )) || null;
}

function areFightersOnSameCityRoof() {
  if (!isCityMap() || !player1 || !player2) return false;
  const roof1 = getCityRooftopNearFighter(player1);
  const roof2 = getCityRooftopNearFighter(player2);
  return Boolean(roof1 && roof1 === roof2);
}

function getCityCameraWeaponPadding() {
  if (!isCityMap()) return 0;
  if (areFightersOnSameCityRoof()) return 170;
  return (isFighterOnCityBuilding(player1) || isFighterOnCityBuilding(player2)) ? 115 : 0;
}

function snapBattleCameraToPlayers() {
  if (!isLargeMap() || !player1 || !player2) return false;
  const marginX = isOceanMap() ? 165 : isCityMap() ? 150 : 120;
  const marginY = (isOceanMap() ? 170 : isCityMap() ? 150 : 100) + getCityCameraWeaponPadding();
  const topMarginY = isOceanMap() ? 245 : marginY;
  const bottomMarginY = isOceanMap() ? 48 : marginY;
  const left = Math.min(player1.x, player2.x) - marginX;
  const right = Math.max(player1.x + player1.width, player2.x + player2.width) + marginX;
  const top = Math.min(player1.y, player2.y) - topMarginY;
  const mapLowPoint = isRiverMap()
    ? getRiverSurfaceY() + 40
    : isCityMap()
      ? (shouldCityCameraKeepRoadVisible() ? getGroundY() + CITY_VISIBLE_ROAD_MARGIN : Math.max(player1.y + player1.height, player2.y + player2.height))
      : isForestMap()
        ? getGroundY() + FOREST_VISIBLE_GROUND_MARGIN
        : isOceanMap()
          ? Math.max(player1.y + player1.height, player2.y + player2.height)
          : getGroundY();
  const bottom = Math.max(player1.y + player1.height, player2.y + player2.height, mapLowPoint) + bottomMarginY;
  const worldWidth = getWorldWidth();
  const worldHeight = getWorldHeight();
  const mapScaleFloor = Math.max(GAME_WIDTH / worldWidth, GAME_HEIGHT / worldHeight);
  const minScale = Math.max(isCityMap() ? 0.38 : 0.5, mapScaleFloor);
  const neededWidth = Math.max(GAME_WIDTH, right - left);
  const neededHeight = Math.max(GAME_HEIGHT, bottom - top);
  const scale = clamp(Math.min(1, GAME_WIDTH / neededWidth, GAME_HEIGHT / neededHeight), minScale, 1);
  const halfWidth = GAME_WIDTH / (2 * scale);
  const halfHeight = GAME_HEIGHT / (2 * scale);
  const minX = Math.min(halfWidth, worldWidth - halfWidth);
  const maxX = Math.max(halfWidth, worldWidth - halfWidth);
  const minY = Math.min(halfHeight, worldHeight - halfHeight);
  const maxY = Math.max(halfHeight, worldHeight - halfHeight);
  battleCamera.x = clamp((left + right) / 2, minX, maxX);
  battleCamera.y = clamp((top + bottom) / 2, minY, maxY);
  battleCamera.scale = scale;
  battleCamera.verticalOutOfFrameTimer = 0;
  battleCamera.cityLadderHoldTimer = 0;
  return true;
}

function resetBattleCamera() {
  if (snapBattleCameraToPlayers()) return;
  battleCamera.x = isLargeMap() ? getWorldWidth() / 2 : GAME_WIDTH / 2;
  battleCamera.y = isLargeMap() ? getGroundY() - GAME_HEIGHT * 0.34 : GAME_HEIGHT / 2;
  battleCamera.scale = 1;
  battleCamera.verticalOutOfFrameTimer = 0;
  battleCamera.cityLadderHoldTimer = 0;
}

function updateBattleCamera() {
  if (!isLargeMap() || !player1 || !player2) {
    resetBattleCamera();
    return;
  }

  const marginX = isOceanMap() ? 165 : isCityMap() ? 150 : 120;
  const cityLadderClimberCount = isCityMap()
    ? Number(Boolean(player1.climbingBuilding)) + Number(Boolean(player2.climbingBuilding))
    : 0;
  const citySingleLadderClimbing = cityLadderClimberCount === 1;
  if (citySingleLadderClimbing) battleCamera.cityLadderHoldTimer = 45;
  const marginY = (isOceanMap() ? 170 : isCityMap() ? 150 : 100) + getCityCameraWeaponPadding();
  const topMarginY = citySingleLadderClimbing ? Math.max(90, marginY * 0.55) : isOceanMap() ? 245 : marginY;
  const bottomMarginY = isOceanMap() ? 48 : marginY;
  const player1Jumping = player1.jumpApexY !== null && !player1.climbingBuilding;
  const player2Jumping = player2.jumpApexY !== null && !player2.climbingBuilding;
  const cameraPlayer1Y = player1Jumping ? player1.cameraAnchorY : player1.y;
  const cameraPlayer2Y = player2Jumping ? player2.cameraAnchorY : player2.y;
  const cameraPlayer1Top = cameraPlayer1Y;
  const cameraPlayer2Top = cameraPlayer2Y;
  const cameraPlayer1Bottom = cameraPlayer1Y + player1.height;
  const cameraPlayer2Bottom = cameraPlayer2Y + player2.height;
  const left = Math.min(player1.x, player2.x) - marginX;
  const right = Math.max(player1.x + player1.width, player2.x + player2.width) + marginX;
  const top = Math.min(cameraPlayer1Top, cameraPlayer2Top) - topMarginY;
  const mapLowPoint = isRiverMap()
    ? getRiverSurfaceY() + 40
    : isCityMap()
      ? (shouldCityCameraKeepRoadVisible() ? getGroundY() + CITY_VISIBLE_ROAD_MARGIN : Math.max(cameraPlayer1Bottom, cameraPlayer2Bottom))
      : isForestMap()
        ? getGroundY() + FOREST_VISIBLE_GROUND_MARGIN
        : isOceanMap()
          ? Math.max(cameraPlayer1Bottom, cameraPlayer2Bottom)
          : getGroundY();
  const bottom = Math.max(cameraPlayer1Bottom, cameraPlayer2Bottom, mapLowPoint) + bottomMarginY;
  const neededWidth = Math.max(GAME_WIDTH, right - left);
  const neededHeight = Math.max(GAME_HEIGHT, bottom - top);
  const worldWidth = getWorldWidth();
  const worldHeight = getWorldHeight();
  const mapScaleFloor = Math.max(GAME_WIDTH / worldWidth, GAME_HEIGHT / worldHeight);
  const minScale = Math.max(isCityMap() ? 0.38 : 0.5, mapScaleFloor);
  const targetScale = clamp(Math.min(1, GAME_WIDTH / neededWidth, GAME_HEIGHT / neededHeight), minScale, 1);
  const halfWidth = GAME_WIDTH / (2 * targetScale);
  const halfHeight = GAME_HEIGHT / (2 * targetScale);
  const minX = Math.min(halfWidth, worldWidth - halfWidth);
  const maxX = Math.max(halfWidth, worldWidth - halfWidth);
  const minY = Math.min(halfHeight, worldHeight - halfHeight);
  const maxY = Math.max(halfHeight, worldHeight - halfHeight);
  const centerX = clamp((left + right) / 2, minX, maxX);
  const centerY = clamp((top + bottom) / 2, minY, maxY);
  const currentHalfHeight = GAME_HEIGHT / (2 * battleCamera.scale);
  const currentHalfWidth = GAME_WIDTH / (2 * battleCamera.scale);
  const frameLeft = battleCamera.x - currentHalfWidth;
  const frameRight = battleCamera.x + currentHalfWidth;
  const frameTop = battleCamera.y - currentHalfHeight;
  const frameBottom = battleCamera.y + currentHalfHeight;
  const horizontallyInsideCurrentFrame =
    player1.x >= frameLeft &&
    player1.x + player1.width <= frameRight &&
    player2.x >= frameLeft &&
    player2.x + player2.width <= frameRight;
  const verticallyInsideCurrentFrame =
    cameraPlayer1Top >= frameTop &&
    cameraPlayer1Bottom <= frameBottom &&
    cameraPlayer2Top >= frameTop &&
    cameraPlayer2Bottom <= frameBottom;
  const fightersInsideCurrentFrame = horizontallyInsideCurrentFrame && verticallyInsideCurrentFrame;
  if (!verticallyInsideCurrentFrame) battleCamera.verticalOutOfFrameTimer += 1;
  const sameCityRoofFight = areFightersOnSameCityRoof();
  const cityLadderClimbing = isCityMap() && Boolean(player1.climbingBuilding || player2.climbingBuilding);
  const verticalDelay = isCityMap()
    ? (sameCityRoofFight ? FPS : FPS * 0.25)
    : isOceanMap()
      ? 2
      : CAMERA_VERTICAL_OUT_OF_FRAME_DELAY;
  const verticalDelayOverrun = Math.max(0, battleCamera.verticalOutOfFrameTimer - verticalDelay);
  const cityVerticalEaseMax = citySingleLadderClimbing ? 0.006 : cityLadderClimbing ? 0.018 : sameCityRoofFight ? 0.018 : 0.055;
  const oceanBothRising =
    isOceanMap() &&
    player1.isUnderwater() &&
    player2.isUnderwater() &&
    player1.velocity.y < -0.2 &&
    player2.velocity.y < -0.2;
  const oceanUpwardEase = oceanBothRising && centerY < battleCamera.y ? 0.18 : 0;
  const verticalEase = Math.max(
    oceanUpwardEase,
    clamp(verticalDelayOverrun / FPS, 0, 1) * (isCityMap() ? cityVerticalEaseMax : isOceanMap() ? 0.24 : 0.035)
  );
  if (verticallyInsideCurrentFrame) battleCamera.verticalOutOfFrameTimer = 0;

  const recentlyExitedCityLadder = isCityMap() && !citySingleLadderClimbing && battleCamera.cityLadderHoldTimer > 0;
  const horizontalMotionAfterLadder =
    recentlyExitedCityLadder &&
    (Math.abs(player1.velocity.x) > 0.2 || Math.abs(player2.velocity.x) > 0.2);
  if (horizontalMotionAfterLadder) battleCamera.cityLadderHoldTimer = 0;
  const holdSingleLadderCamera =
    isCityMap() &&
    ((citySingleLadderClimbing && fightersInsideCurrentFrame) || (recentlyExitedCityLadder && !horizontalMotionAfterLadder));
  if (!citySingleLadderClimbing && battleCamera.cityLadderHoldTimer > 0 && !fightersInsideCurrentFrame) {
    battleCamera.cityLadderHoldTimer -= 1;
  }
  if (!holdSingleLadderCamera) {
    battleCamera.x += (centerX - battleCamera.x) * (isOceanMap() ? 0.18 : 0.12);
  }
  if (!holdSingleLadderCamera && verticalEase > 0) {
    battleCamera.y += (centerY - battleCamera.y) * verticalEase;
  }
  if (isOceanMap() && !holdSingleLadderCamera) {
    const visibleTop = battleCamera.y - currentHalfHeight;
    const visibleBottom = battleCamera.y + currentHalfHeight;
    const dangerTop = Math.min(cameraPlayer1Top, cameraPlayer2Top) - visibleTop;
    const dangerBottom = visibleBottom - Math.max(cameraPlayer1Bottom, cameraPlayer2Bottom);
    if (dangerTop < 38) battleCamera.y -= (38 - dangerTop) * 0.38;
    if (dangerBottom < 48) battleCamera.y += (48 - dangerBottom) * 0.38;
  }
  const scaleEase = holdSingleLadderCamera
    ? 0
    : citySingleLadderClimbing
      ? 0.01
      : cityLadderClimbing
        ? 0.035
        : isOceanMap()
          ? 0.2
          : 0.1;
  battleCamera.scale += (targetScale - battleCamera.scale) * scaleEase;
  battleCamera.scale = Math.max(battleCamera.scale, minScale);

  const actualHalfWidth = GAME_WIDTH / (2 * battleCamera.scale);
  const actualHalfHeight = GAME_HEIGHT / (2 * battleCamera.scale);
  const actualMinX = Math.min(actualHalfWidth, worldWidth - actualHalfWidth);
  const actualMaxX = Math.max(actualHalfWidth, worldWidth - actualHalfWidth);
  const actualMinY = Math.min(actualHalfHeight, worldHeight - actualHalfHeight);
  const actualMaxY = Math.max(actualHalfHeight, worldHeight - actualHalfHeight);
  battleCamera.x = clamp(battleCamera.x, actualMinX, actualMaxX);
  battleCamera.y = clamp(battleCamera.y, actualMinY, actualMaxY);
}

function applyBattleCamera() {
  ctx.translate(GAME_WIDTH / 2, GAME_HEIGHT / 2);
  ctx.scale(battleCamera.scale, battleCamera.scale);
  ctx.translate(-battleCamera.x, -battleCamera.y);
}

function clipToWorldBounds() {
  ctx.beginPath();
  ctx.rect(0, 0, getWorldWidth(), getWorldHeight());
  ctx.clip();
}

function drawWorldBoundary() {
  ctx.save();
  ctx.strokeStyle = 'rgba(215, 230, 245, 0.28)';
  ctx.lineWidth = 3 / battleCamera.scale;
  ctx.strokeRect(1, 1, getWorldWidth() - 2, getWorldHeight() - 2);
  ctx.restore();
}

const hitEffects = [];
const lifeStealEffects = [];
const PERFORMANCE_LIMITS = {
  hitEffects: 90,
  lifeStealEffects: 10,
  bullets: 95,
  grenades: 12,
  bombs: 12,
  magicFireballs: 16,
  hunterBolts: 30,
  hunterTraps: 12,
  royalArrows: 18,
  royalArrowParticles: 170,
  gunnerRockets: 8,
  cosmicEvents: 3,
  cosmicHazards: 18,
  sorcererClones: 10,
  abyssalClones: 4,
  volcanoHazards: 22,
  volcanoMagmaFlows: 10,
  volcanoMagmaShots: 14,
  stormZones: 4,
  stormShockwaves: 10,
  frostSnowballs: 8,
  frostIcicles: 36,
  ashFlames: 32,
  ashTurrets: 4,
  oceanXpOrbs: 28,
};

function trimOldest(array, maxLength) {
  if (array.length > maxLength) array.splice(0, array.length - maxLength);
}

function enforcePerformanceCaps() {
  trimOldest(hitEffects, PERFORMANCE_LIMITS.hitEffects);
  trimOldest(lifeStealEffects, PERFORMANCE_LIMITS.lifeStealEffects);
  trimOldest(bullets, PERFORMANCE_LIMITS.bullets);
  trimOldest(grenades, PERFORMANCE_LIMITS.grenades);
  trimOldest(bombs, PERFORMANCE_LIMITS.bombs);
  trimOldest(magicFireballs, PERFORMANCE_LIMITS.magicFireballs);
  trimOldest(hunterBolts, PERFORMANCE_LIMITS.hunterBolts);
  trimOldest(hunterTraps, PERFORMANCE_LIMITS.hunterTraps);
  trimOldest(royalArrows, PERFORMANCE_LIMITS.royalArrows);
  trimOldest(royalArrowParticles, PERFORMANCE_LIMITS.royalArrowParticles);
  trimOldest(gunnerRockets, PERFORMANCE_LIMITS.gunnerRockets);
  trimOldest(cosmicEvents, PERFORMANCE_LIMITS.cosmicEvents);
  trimOldest(cosmicHazards, PERFORMANCE_LIMITS.cosmicHazards);
  trimOldest(sorcererClones, PERFORMANCE_LIMITS.sorcererClones);
  trimOldest(abyssalClones, PERFORMANCE_LIMITS.abyssalClones);
  trimOldest(volcanoHazards, PERFORMANCE_LIMITS.volcanoHazards);
  trimOldest(volcanoMagmaFlows, PERFORMANCE_LIMITS.volcanoMagmaFlows);
  trimOldest(volcanoMagmaShots, PERFORMANCE_LIMITS.volcanoMagmaShots);
  trimOldest(stormZones, PERFORMANCE_LIMITS.stormZones);
  trimOldest(stormShockwaves, PERFORMANCE_LIMITS.stormShockwaves);
  trimOldest(frostSnowballs, PERFORMANCE_LIMITS.frostSnowballs);
  trimOldest(frostIcicles, PERFORMANCE_LIMITS.frostIcicles);
  trimOldest(ashFlames, PERFORMANCE_LIMITS.ashFlames);
  trimOldest(ashTurrets, PERFORMANCE_LIMITS.ashTurrets);
  trimOldest(oceanXpOrbs, PERFORMANCE_LIMITS.oceanXpOrbs);
}

