let recreationalMode = null;
let recreationalSpeedAccumulator = 0;
let kingPlatformState = null;
let huntedModeState = null;
let borderShrinkState = null;
let oneVsAllState = null;
let draftModeState = null;
let swapPickups = [];
let swapPickupSpawnTimer = 0;
let tutorialStepIndex = 0;
let tutorialDismissedThisSession = false;
let tutorialMode = false;
let tutorialStepStart = null;
let tutorialDummyAnchor = null;
let tutorialInputs = {};
let tutorialAdvanceDelay = 0;
let tutorialDummyMoveTimer = 0;
