const TUTORIAL_STEP_ADVANCE_DELAY = 2 * FPS;

function getRecreationalSpeedScale() {
  return recreationalMode?.speedScale || 1;
}

function getRecreationalDamageValue(dmg) {
  if (!recreationalMode || !Number.isFinite(dmg) || dmg <= 0) return dmg;
  if (recreationalMode.type === 'hunted') return dmg;
  if (recreationalMode.oneTap) return 999999;
  return +(dmg * (recreationalMode.damageMultiplier || 1)).toFixed(2);
}

function getHuntedRoleForFighter(fighter) {
  if (recreationalMode?.type !== 'hunted' || !huntedModeState || !fighter) return null;
  const key = fighter === player1 ? 'player1' : fighter === player2 ? 'player2' : null;
  if (!key) return null;
  return key === huntedModeState.huntedPlayer ? 'hunted' : 'hunter';
}

function getHuntedDamageMultiplier(fighter) {
  const role = getHuntedRoleForFighter(fighter);
  if (role === 'hunter') return 2;
  return 1;
}

function getHuntedMoveMultiplier(fighter) {
  const role = getHuntedRoleForFighter(fighter);
  if (role === 'hunted') return 1.16;
  if (role === 'hunter') return 0.92;
  return 1;
}

function getPendingRecreationalModeLabel(mode = pendingRecreationalMode) {
  if (!mode) return '';
  if (mode.type === 'swapWeapons') return 'weapon-swap';
  if (mode.type === 'swapAbilities') return 'ability-swap';
  if (mode.type === 'randomSpeed') return 'random-speed';
  if (mode.type === 'speed') {
    if (mode.speedScale === 0.5) return 'half-speed';
    if (mode.speedScale === 2) return 'double-speed';
    return 'triple-speed';
  }
  if (mode.type === 'oneTap') return 'one-tap';
  if (mode.type === 'damage') {
    if (mode.damageMultiplier === 0.5) return 'half-damage';
    if (mode.damageMultiplier === 2) return 'double-damage';
    return 'triple-damage';
  }
  if (mode.type === 'kingPlatform') return 'king-of-the-platform';
  if (mode.type === 'hunted') return 'hunted';
  if (mode.type === 'borderShrink') return mode.axis === 'vertical' ? 'vertical-border-shrink' : 'border-shrink';
  if (mode.type === 'oneVsAll') return 'one-vs-all';
  if (mode.type === 'draft') return 'draft';
  return 'recreational';
}

function getDraftModePool() {
  const unlocked = getPlayer1UnlockedCharacterKeys().filter((key) => characterTypes[key]);
  return unlocked.length ? unlocked : ['swordMaster'];
}

function makeDraftOffer(pool, count = 2, excluded = []) {
  const excludedSet = new Set(excluded.filter(Boolean));
  let source = pool.filter((key) => !excludedSet.has(key));
  if (source.length < Math.min(count, pool.length)) source = pool.slice();
  const offer = [];
  while (source.length && offer.length < count) {
    const index = Math.floor(Math.random() * source.length);
    offer.push(source.splice(index, 1)[0]);
  }
  return offer;
}

function createDraftCardButton(key, onPick, selected = false) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = `draft-card-button${selected ? ' selected' : ''}`;
  button.appendChild(createBossCharacterPortrait(key, 92, 82));
  const name = document.createElement('div');
  name.className = 'draft-card-name';
  name.textContent = characterTypes[key]?.name || key;
  button.appendChild(name);
  button.addEventListener('click', () => onPick(key));
  return button;
}

function resetDraftModeState() {
  const pool = getDraftModePool();
  draftModeState = {
    phase: 'draft',
    round: 1,
    pool,
    offers: {
      player1: makeDraftOffer(pool),
      player2: makeDraftOffer(pool),
    },
    picks: {
      player1: [],
      player2: [],
    },
    final: {
      player1: null,
      player2: null,
    },
  };
}

function advanceDraftModeIfReady() {
  if (!draftModeState) return;
  if (draftModeState.phase === 'draft') {
    const p1Ready = draftModeState.picks.player1.length >= draftModeState.round;
    const p2Ready = draftModeState.picks.player2.length >= draftModeState.round;
    if (!p1Ready || !p2Ready) return;
    if (draftModeState.round < 2) {
      draftModeState.round += 1;
      draftModeState.offers = {
        player1: makeDraftOffer(draftModeState.pool, 2, draftModeState.picks.player1),
        player2: makeDraftOffer(draftModeState.pool, 2, draftModeState.picks.player2),
      };
    } else {
      draftModeState.phase = 'final';
    }
    renderDraftModeScreen();
    return;
  }
  if (draftModeState.phase === 'final' && draftModeState.final.player1 && draftModeState.final.player2) {
    pendingRecreationalMode = {
      type: 'draft',
      speedScale: 1,
      player1Key: draftModeState.final.player1,
      player2Key: draftModeState.final.player2,
    };
    recreationalMode = null;
    recreationalSpeedAccumulator = 0;
    draftModeState = null;
    showMapChoiceScreen(false);
  }
}

function pickDraftCard(side, key) {
  if (!draftModeState || draftModeState.phase !== 'draft') return;
  if (!draftModeState.offers[side]?.includes(key)) return;
  const picks = draftModeState.picks[side];
  picks[draftModeState.round - 1] = key;
  playSound('ui', 35);
  renderDraftModeScreen();
  advanceDraftModeIfReady();
}

function pickDraftFinal(side, key) {
  if (!draftModeState || draftModeState.phase !== 'final') return;
  if (!draftModeState.picks[side]?.includes(key)) return;
  draftModeState.final[side] = key;
  playSound('ui', 35);
  renderDraftModeScreen();
  advanceDraftModeIfReady();
}

function renderDraftPlayerPanel(side, label) {
  const panel = document.createElement('div');
  panel.className = 'draft-player-panel';
  const title = document.createElement('h3');
  title.textContent = label;
  panel.appendChild(title);
  const grid = document.createElement('div');
  grid.className = 'draft-card-grid';
  if (draftModeState.phase === 'draft') {
    const lockedPick = draftModeState.picks[side][draftModeState.round - 1];
    for (const key of draftModeState.offers[side]) {
      grid.appendChild(createDraftCardButton(key, (pickedKey) => pickDraftCard(side, pickedKey), key === lockedPick));
    }
    if (lockedPick) {
      const msg = document.createElement('div');
      msg.className = 'draft-lock-message';
      msg.textContent = `${characterTypes[lockedPick]?.name || lockedPick} drafted.`;
      panel.appendChild(grid);
      panel.appendChild(msg);
      return panel;
    }
  } else {
    for (const key of draftModeState.picks[side]) {
      grid.appendChild(createDraftCardButton(key, (pickedKey) => pickDraftFinal(side, pickedKey), key === draftModeState.final[side]));
    }
  }
  panel.appendChild(grid);
  return panel;
}

function renderDraftModeScreen() {
  if (!draftModeBoard || !draftModePrompt || !draftModeState) return;
  draftModeBoard.innerHTML = '';
  draftModePrompt.textContent = draftModeState.phase === 'draft'
    ? `Draft ${draftModeState.round}/2: each player picks one card from their two.`
    : 'Final choice: each player chooses which of their two drafted characters to use.';
  draftModeBoard.appendChild(renderDraftPlayerPanel('player1', 'Player 1'));
  draftModeBoard.appendChild(renderDraftPlayerPanel('player2', 'Player 2'));
}

