function getOneVsAllPlayableKeys() {
  const unlocked = getUnlockedCharacterKeysFromShards();
  const pool = (unlocked.length ? unlocked : ['swordMaster']).filter((key) => characterTypes[key]);
  return pool.length ? pool : ['swordMaster'];
}

function populateOneVsAllCharacterSelect() {
  if (!oneVsAllCharacterSelect) return;
  const previous = oneVsAllCharacterSelect.value;
  const keys = getOneVsAllPlayableKeys();
  oneVsAllCharacterSelect.innerHTML = '';
  for (const key of keys) {
    const option = document.createElement('option');
    option.value = key;
    option.textContent = characterTypes[key]?.name || key;
    oneVsAllCharacterSelect.appendChild(option);
  }
  oneVsAllCharacterSelect.value = keys.includes(previous) ? previous : keys[0];
}

function startOneVsAllMode() {
  const chosenKey = oneVsAllCharacterSelect?.value || getOneVsAllPlayableKeys()[0] || 'swordMaster';
  const allKeys = CHARACTER_UNLOCK_ORDER.filter((key) => characterTypes[key]);
  const otherKeys = allKeys.filter((key) => key !== chosenKey);
  const soloOnLeft = Math.random() < 0.5;
  const soloKey = chosenKey;
  const armyKeys = otherKeys;
  const firstChallengerKey = armyKeys[0] || 'swordMaster';
  aiMode = false;
  bossMode = false;
  tournamentMode = false;
  tournamentFinished = false;
  pendingRecreationalMode = {
    type: 'oneVsAll',
    speedScale: 1,
    chosenKey,
    soloOnLeft,
    userIsSolo: soloOnLeft,
    soloKey,
    armyKeys,
    player1Key: soloOnLeft ? soloKey : firstChallengerKey,
    player2Key: soloOnLeft ? firstChallengerKey : soloKey,
  };
  recreationalMode = null;
  recreationalSpeedAccumulator = 0;
  oneVsAllState = null;
  setRestartButtonMode('Exit Match');
  updateTournamentStatus();
  updateGameModeLabels();
  showMapChoiceScreen(false);
}

