function unlockRecreationalMode(unlockKey, cost, label) {
  if (adminUnlockActive || progression.recreationalUnlocks?.[unlockKey]) return true;
  if (progression.gold < cost) {
    showModeUnlockMessage(`${label} costs ${cost.toLocaleString()} gold.`);
    playSound('ui', 40);
    return false;
  }
  progression.gold -= cost;
  progression.recreationalUnlocks = progression.recreationalUnlocks || {};
  progression.recreationalUnlocks[unlockKey] = true;
  saveProgression();
  updateScoreUI();
  updateRecreationalUnlockUI();
  showModeUnlockMessage(`${label} unlocked.`);
  return true;
}

