function showAiDuelScreen() {
  if (!adminUnlockActive) {
    showModeUnlockMessage('AI Duel Test is available after Admin Unlock.');
    playSound('ui', 40);
    return;
  }
  setGameControlsInMatch(false);
  clearRecreationalMode();
  startScreen.classList.add('hidden');
  hideHumanCharacterScreen();
  hideTutorial(false);
  hideTournamentOpponentChoice();
  hideMapChoiceScreen();
  hideRecreationalScreens();
  hideBossFormationScreen();
  hideRosterScreen();
  renderAiDuelRooms();
  renderAiDuelLeaderboard();
  aiDuelScreen?.classList.remove('hidden');
  canvas.classList.add('hidden');
  statusBar.classList.add('hidden');
  playSound('ui', 40);
}

function recordAiDuelResult(winner, player1Key = player1?.characterTypeKey, player2Key = player2?.characterTypeKey) {
  if (!player1Key || !player2Key) return;
  if (!aiDuelStats[player1Key]) aiDuelStats[player1Key] = { wins: 0, games: 0 };
  if (!aiDuelStats[player2Key]) aiDuelStats[player2Key] = { wins: 0, games: 0 };
  aiDuelStats[player1Key].games += 1;
  aiDuelStats[player2Key].games += 1;
  aiDuelStats[winner === 'Player 1' ? player1Key : player2Key].wins += 1;
  saveAiDuelStats();
  renderAiDuelLeaderboard();
  if (liveAiDuelLeaderboardPanel && !liveAiDuelLeaderboardPanel.hidden) {
    renderAiDuelLeaderboard(liveAiDuelLeaderboardEl);
  }
}

function clearAiDuelAutoContinue() {
  if (!aiDuelAutoContinueTimer) return;
  clearTimeout(aiDuelAutoContinueTimer);
  aiDuelAutoContinueTimer = null;
}

function stopAiDuelRoomRunner() {
  if (!aiDuelRoomInterval) return;
  clearInterval(aiDuelRoomInterval);
  aiDuelRoomInterval = null;
}

function setLiveAiDuelLeaderboardOpen(open) {
  if (!liveAiDuelLeaderboardPanel || !liveAiDuelLeaderboardButton) return;
  const shouldOpen = Boolean(open && aiDuelMode);
  liveAiDuelLeaderboardPanel.hidden = !shouldOpen;
  liveAiDuelLeaderboardButton.setAttribute('aria-expanded', String(shouldOpen));
  if (shouldOpen) renderAiDuelLeaderboard(liveAiDuelLeaderboardEl);
}

function updateLiveAiDuelLeaderboardVisibility() {
  if (!liveAiDuelLeaderboardButton) return;
  liveAiDuelLeaderboardButton.hidden = !aiDuelMode;
  if (!aiDuelMode) setLiveAiDuelLeaderboardOpen(false);
}

function getAiDuelCharacterLabel(key) {
  return characterTypes[key]?.name?.replace(/^The /, '') || key;
}

function getRandomAiDuelOpponent(excludedKey) {
  const unlocked = getUnlockedCharacterKeysFromShards();
  const pool = unlocked.filter((key) => key !== excludedKey);
  if (pool.length) return pool[Math.floor(Math.random() * pool.length)];
  return getRandomTournamentCharacter();
}

function getAiDuelSimMaxHealth(characterKey) {
  const health = getPartHealthConfig(characterKey);
  return health.head + health.torso + health.limbs * 4;
}

function resetAiDuelRoomSimHealth(room) {
  room.simP1Hp = getAiDuelSimMaxHealth(room.player1Key);
  room.simP2Hp = getAiDuelSimMaxHealth(room.player2Key);
}

function createAiDuelRoom(index, observed = false) {
  const player1Key = getRandomTournamentCharacter();
  const player2Key = getRandomAiDuelOpponent(player1Key);
  const room = {
    index,
    player1Key,
    player2Key,
    observed,
    roomWins: { player1: 0, player2: 0 },
    games: 0,
    status: observed ? 'On TV' : 'Running live',
    matchState: null,
    aiStateP1: createAiControllerState(),
    aiStateP2: createAiControllerState(),
    restartDelay: 0,
    resultRecorded: false,
  };
  resetAiDuelRoomSimHealth(room);
  return room;
}

function resetAiDuelRoomMatch(room) {
  if (!room) return;
  room.player1Key = getRandomTournamentCharacter();
  room.player2Key = getRandomAiDuelOpponent(room.player1Key);
  room.restartDelay = 0;
  room.resultRecorded = false;
  syncAiDuelRoomStatus(room);
  resetAiDuelRoomSimHealth(room);
  initializeAiDuelRoomMatch(room);
}

function syncArrayState(target, source) {
  target.length = 0;
  if (source?.length) target.push(...source);
}

function saveAiDuelRoomState(room) {
  if (!room || !player1 || !player2) return;
  room.matchState = {
    player1,
    player2,
    matchWinner,
    activeMap,
    platforms: platforms.slice(),
    forestTrees: forestTrees.slice(),
    cityBuildings: cityBuildings.slice(),
    oceanSharks: oceanSharks.slice(),
    oceanSardines: oceanSardines.slice(),
    oceanXpOrbs: oceanXpOrbs.slice(),
    oceanSharkSpawnTimer,
    oceanSardineSpawnTimer,
    volcanoHazards: volcanoHazards.slice(),
    volcanoMagmaFlows: volcanoMagmaFlows.slice(),
    volcanoMagmaShots: volcanoMagmaShots.slice(),
    volcanoEruptionTimer,
    stormZones: stormZones.slice(),
    stormShockwaves: stormShockwaves.slice(),
    ashFlames: ashFlames.slice(),
    ashTurrets: ashTurrets.slice(),
    bombs: bombs.slice(),
    bullets: bullets.slice(),
    grenades: grenades.slice(),
    magicFireballs: magicFireballs.slice(),
    cosmicEvents: cosmicEvents.slice(),
    cosmicHazards: cosmicHazards.slice(),
    sorcererClones: sorcererClones.slice(),
    abyssalClones: abyssalClones.slice(),
    hunterBolts: hunterBolts.slice(),
    hunterTraps: hunterTraps.slice(),
    royalArrows: royalArrows.slice(),
    royalArrowParticles: royalArrowParticles.slice(),
    gunnerRockets: gunnerRockets.slice(),
    frostSnowballs: frostSnowballs.slice(),
    frostIcicles: frostIcicles.slice(),
    hitEffects: hitEffects.slice(),
    lifeStealEffects: lifeStealEffects.slice(),
    battleCamera: { ...battleCamera },
  };
  room.simP1Hp = Math.max(0, player1.totalHealth());
  room.simP2Hp = Math.max(0, player2.totalHealth());
}

function loadAiDuelRoomState(room) {
  if (!room?.matchState) {
    initializeAiDuelRoomMatch(room);
  }
  const state = room.matchState;
  player1 = state.player1;
  player2 = state.player2;
  matchWinner = state.matchWinner;
  activeMap = state.activeMap;
  platforms = state.platforms || [];
  forestTrees = state.forestTrees || [];
  cityBuildings = state.cityBuildings || [];
  oceanSharks = state.oceanSharks || [];
  oceanSardines = state.oceanSardines || [];
  oceanXpOrbs = state.oceanXpOrbs || [];
  oceanSharkSpawnTimer = state.oceanSharkSpawnTimer || 0;
  oceanSardineSpawnTimer = state.oceanSardineSpawnTimer || 0;
  volcanoHazards = state.volcanoHazards || [];
  volcanoMagmaFlows = state.volcanoMagmaFlows || [];
  volcanoMagmaShots = state.volcanoMagmaShots || [];
  volcanoEruptionTimer = state.volcanoEruptionTimer || 0;
  stormZones = state.stormZones || [];
  stormShockwaves = state.stormShockwaves || [];
  ashFlames = state.ashFlames || [];
  ashTurrets = state.ashTurrets || [];
  syncArrayState(bombs, state.bombs);
  syncArrayState(bullets, state.bullets);
  syncArrayState(grenades, state.grenades);
  syncArrayState(magicFireballs, state.magicFireballs);
  syncArrayState(cosmicEvents, state.cosmicEvents);
  syncArrayState(cosmicHazards, state.cosmicHazards);
  syncArrayState(sorcererClones, state.sorcererClones);
  syncArrayState(abyssalClones, state.abyssalClones);
  syncArrayState(hunterBolts, state.hunterBolts);
  syncArrayState(hunterTraps, state.hunterTraps);
  syncArrayState(royalArrows, state.royalArrows);
  syncArrayState(royalArrowParticles, state.royalArrowParticles);
  syncArrayState(gunnerRockets, state.gunnerRockets);
  syncArrayState(frostSnowballs, state.frostSnowballs);
  syncArrayState(frostIcicles, state.frostIcicles);
  syncArrayState(hitEffects, state.hitEffects);
  syncArrayState(lifeStealEffects, state.lifeStealEffects);
  Object.assign(battleCamera, state.battleCamera || {});
  aiDuelStateP1 = room.aiStateP1;
  aiDuelStateP2 = room.aiStateP2;
}

function initializeAiDuelRoomMatch(room) {
  if (!room) return;
  const previousSuppress = suppressHiddenRoomAudio;
  suppressHiddenRoomAudio = true;
  const previousObservedIndex = aiDuelObservedRoomIndex;
  setupPlayers(room.player1Key, room.player2Key, 'random');
  suppressHiddenRoomAudio = previousSuppress;
  room.aiStateP1 = createAiControllerState();
  room.aiStateP2 = createAiControllerState();
  aiDuelStateP1 = room.aiStateP1;
  aiDuelStateP2 = room.aiStateP2;
  room.matchState = null;
  saveAiDuelRoomState(room);
  aiDuelObservedRoomIndex = previousObservedIndex;
}

function chooseAiDuelRoomWinner(room) {
  const p1Stats = aiDuelStats[room.player1Key] || { wins: 0, games: 0 };
  const p2Stats = aiDuelStats[room.player2Key] || { wins: 0, games: 0 };
  const p1Rate = p1Stats.games > 3 ? p1Stats.wins / p1Stats.games : 0.5;
  const p2Rate = p2Stats.games > 3 ? p2Stats.wins / p2Stats.games : 0.5;
  const p1Chance = clamp(0.5 + (p1Rate - p2Rate) * 0.22 + randomBetween(-0.12, 0.12), 0.35, 0.65);
  return Math.random() < p1Chance ? 'Player 1' : 'Player 2';
}

function recordAiDuelRoomResult(room, winner) {
  if (!room || room.resultRecorded) return;
  room.resultRecorded = true;
  room.games += 1;
  if (winner === 'Player 1') room.roomWins.player1 += 1;
  else room.roomWins.player2 += 1;
  recordAiDuelResult(winner, room.player1Key, room.player2Key);
  room.status = `${winner === 'Player 1' ? getAiDuelCharacterLabel(room.player1Key) : getAiDuelCharacterLabel(room.player2Key)} won`;
}

function syncAiDuelRoomStatus(room) {
  if (!room) return;
  if (room.resultRecorded) return;
  room.status = room.observed ? 'On TV' : 'Running live';
}

function getAiDuelRoomHealthLabel(room) {
  if (room.restartDelay > 0) return 'Next fight';
  const state = room.matchState;
  const p1 = Math.max(0, Math.ceil(state?.player1?.totalHealth?.() ?? room.simP1Hp ?? getAiDuelSimMaxHealth(room.player1Key)));
  const p2 = Math.max(0, Math.ceil(state?.player2?.totalHealth?.() ?? room.simP2Hp ?? getAiDuelSimMaxHealth(room.player2Key)));
  return `${room.index === aiDuelObservedRoomIndex ? 'Watching' : 'Live'} HP ${p1}-${p2}`;
}

function resolveLoadedAiDuelRoomWinner(room, observed) {
  if (matchWinner || !player1 || !player2) return !!matchWinner;
  if (!player1.dead && !player2.dead) return false;
  matchWinner = player1.dead ? 'Player 2' : 'Player 1';
  recordAiDuelRoomResult(room, matchWinner);
  if (observed) {
    room.restartDelay = 66;
    updateMatchReturnButton();
    scheduleAiDuelAutoContinue();
  } else {
    room.restartDelay = 66;
  }
  return true;
}

function updateLoadedAiDuelRoomFrame(room, observed = false) {
  if (!room || !player1 || !player2) return;
  enforcePerformanceCaps();
  if (matchWinner) {
    clearActiveAttacks();
    room.restartDelay = Math.max(0, (room.restartDelay || 0) - 1);
    if (room.restartDelay <= 0) {
      resetAiDuelRoomMatch(room);
      loadAiDuelRoomState(room);
    }
    enforcePerformanceCaps();
    return;
  }
  updateAIControllerFor(player1, player2, room.aiStateP1);
  updateAIControllerFor(player2, player1, room.aiStateP2);
  if (resolveLoadedAiDuelRoomWinner(room, observed)) return;
  updateMovingPlatforms();
  updateForestTrees();
  updateOceanLife();
  updateVolcanoHazards();
  if (resolveLoadedAiDuelRoomWinner(room, observed)) return;
  player1.update();
  if (resolveLoadedAiDuelRoomWinner(room, observed)) return;
  player2.update();
  if (resolveLoadedAiDuelRoomWinner(room, observed)) return;
  updateBullets();
  updateHunterBolts();
  updateRoyalArrows();
  updateGunnerRockets();
  updateFrostProjectiles();
  updateAshEngineerEffects();
  updateHunterTraps();
  updateMagicFireballs();
  updateGrenades();
  updateBombs();
  updateCosmicCollapse();
  updateStormRoninEffects();
  updateAbyssalClones();
  if (resolveLoadedAiDuelRoomWinner(room, observed)) return;
  detectAttacks();
  resolveLoadedAiDuelRoomWinner(room, observed);
  enforcePerformanceCaps();
}

function updateAiDuelRoomsFrame() {
  if (!aiDuelMode || !aiDuelRooms.length) return;
  const observedIndex = aiDuelObservedRoomIndex;
  for (const room of aiDuelRooms) {
    loadAiDuelRoomState(room);
    suppressHiddenRoomAudio = room.index !== observedIndex;
    aiDuelActiveRoom = room;
    try {
      updateLoadedAiDuelRoomFrame(room, room.index === observedIndex);
      saveAiDuelRoomState(room);
    } finally {
      aiDuelActiveRoom = null;
      suppressHiddenRoomAudio = false;
    }
  }
  loadAiDuelRoomState(aiDuelRooms[observedIndex]);
  updateHealthUI();
  if (liveAiDuelLeaderboardPanel && !liveAiDuelLeaderboardPanel.hidden) {
    renderAiDuelLeaderboard(liveAiDuelLeaderboardEl);
  }
  aiDuelRoomRenderCooldown -= 1;
  if (aiDuelRoomRenderCooldown <= 0) {
    aiDuelRoomRenderCooldown = 12;
    renderAiDuelRooms();
  }
}

function renderAiDuelRooms() {
  const renderEmpty = '';
  if (!aiDuelRooms.length) {
    if (aiDuelRoomsEl) aiDuelRoomsEl.innerHTML = renderEmpty;
    if (aiDuelRoomOverlay) {
      aiDuelRoomOverlay.innerHTML = '';
      aiDuelRoomOverlay.hidden = true;
    }
    return;
  }
  const markup = aiDuelRooms.map((room) => `
    <button class="ai-duel-room ${room.index === aiDuelObservedRoomIndex ? 'is-observed' : ''}" type="button" data-room-index="${room.index}">
      <span class="ai-duel-room-title">
        <span>Room ${room.index + 1}</span>
        <span>${getAiDuelRoomHealthLabel(room)}</span>
      </span>
      <span class="ai-duel-room-matchup">${getAiDuelCharacterLabel(room.player1Key)}<br>vs ${getAiDuelCharacterLabel(room.player2Key)}</span>
      <span class="ai-duel-room-status">${room.status} | ${room.roomWins.player1}-${room.roomWins.player2}</span>
    </button>
  `).join('');
  if (aiDuelRoomsEl) aiDuelRoomsEl.innerHTML = markup;
  if (aiDuelRoomOverlay) {
    aiDuelRoomOverlay.innerHTML = markup;
    aiDuelRoomOverlay.hidden = !aiDuelMode;
  }
  if (liveAiDuelLeaderboardPanel && !liveAiDuelLeaderboardPanel.hidden) {
    renderAiDuelLeaderboard(liveAiDuelLeaderboardEl);
  }
}

function tickAiDuelRooms() {
  renderAiDuelRooms();
}

function startAiDuelRoomRunner() {
  stopAiDuelRoomRunner();
  renderAiDuelRooms();
}

function observeAiDuelRoom(index) {
  if (!aiDuelRooms[index]) return;
  if (aiDuelRooms[aiDuelObservedRoomIndex] && aiDuelObservedRoomIndex !== index) {
    const previousRoom = aiDuelRooms[aiDuelObservedRoomIndex];
    saveAiDuelRoomState(previousRoom);
    previousRoom.observed = false;
    syncAiDuelRoomStatus(previousRoom);
  }
  aiDuelObservedRoomIndex = index;
  const room = aiDuelRooms[index];
  room.observed = true;
  syncAiDuelRoomStatus(room);
  clearAiDuelAutoContinue();
  loadAiDuelRoomState(room);
  updateHealthUI();
  aiDuelRoomRenderCooldown = 12;
  renderAiDuelRooms();
}

function scheduleAiDuelAutoContinue() {
  clearAiDuelAutoContinue();
}

function startAiDuelMatch() {
  if (!adminUnlockActive) {
    showModeUnlockMessage('AI Duel Test is available after Admin Unlock.');
    playSound('ui', 40);
    return;
  }
  clearAiDuelAutoContinue();
  aiDuelMode = true;
  aiDuelRooms = Array.from({ length: AI_DUEL_ROOM_COUNT }, (_, index) => createAiDuelRoom(index, index === 0));
  aiDuelObservedRoomIndex = 0;
  aiDuelRoomRenderCooldown = 0;
  aiDuelStateP1 = createAiControllerState();
  aiDuelStateP2 = createAiControllerState();
  aiMode = false;
  bossMode = false;
  tutorialMode = false;
  tournamentMode = false;
  tournamentFinished = false;
  clearRecreationalMode();
  aiDifficulty = aiDifficultySelect.value;
  updateGameModeLabels();
  setRestartButtonMode('Exit AI Duel');
  startAiDuelRoomRunner();
  renderAiDuelRooms();
  updateLiveAiDuelLeaderboardVisibility();
  observeAiDuelRoom(aiDuelObservedRoomIndex);
}

function endAiDuelMode() {
  clearAiDuelAutoContinue();
  stopAiDuelRoomRunner();
  aiDuelMode = false;
  aiDuelRooms = [];
  if (aiDuelRoomOverlay) aiDuelRoomOverlay.hidden = true;
  aiDuelStateP1 = null;
  aiDuelStateP2 = null;
  updateLiveAiDuelLeaderboardVisibility();
  clearAIControls(player1Controls);
  clearAIControls(player2Controls);
  setRestartButtonMode('Restart');
  showAiDuelScreen();
}

