function updateRandomRecreationalSpeed() {
  if (recreationalMode?.type !== 'randomSpeed' || matchWinner || bossMode) return;
  recreationalMode.rerollTimer = Math.max(0, (recreationalMode.rerollTimer || 0) - 1);
  if (recreationalMode.rerollTimer > 0) return;
  recreationalMode.speedScale = rollRandomRecreationalSpeed();
  recreationalMode.rerollTimer = RANDOM_SPEED_REROLL_INTERVAL;
  showModeUnlockMessage(`Speed changed: ${recreationalMode.speedScale.toFixed(2)}x`);
}

function initializeRecreationalRuleState() {
  kingPlatformState = null;
  huntedModeState = null;
  borderShrinkState = null;
  oneVsAllState = null;
  swapPickups = [];
  swapPickupSpawnTimer = 0;
  if (!recreationalMode || !player1 || !player2) return;
  if (recreationalMode.type === 'kingPlatform') {
    const worldCenterX = getWorldWidth() / 2;
    const validPlatforms = platforms.filter((platform) => !platform.moving && !platform.oceanIsland);
    const zonePlatform = (validPlatforms.length ? validPlatforms : platforms)
      .slice()
      .sort((a, b) => Math.abs((a.x + a.width / 2) - worldCenterX) - Math.abs((b.x + b.width / 2) - worldCenterX))[0];
    const floorY = getGroundY();
    kingPlatformState = {
      scores: { player1: 0, player2: 0 },
      tick: 0,
      zone: zonePlatform
        ? {
            x: zonePlatform.x + zonePlatform.width / 2 - KING_PLATFORM_ZONE_WIDTH / 2,
            y: zonePlatform.y - KING_PLATFORM_ZONE_HEIGHT,
            width: KING_PLATFORM_ZONE_WIDTH,
            height: KING_PLATFORM_ZONE_HEIGHT,
          }
        : {
            x: getWorldWidth() / 2 - KING_PLATFORM_ZONE_WIDTH / 2,
            y: floorY - KING_PLATFORM_ZONE_HEIGHT,
            width: KING_PLATFORM_ZONE_WIDTH,
            height: KING_PLATFORM_ZONE_HEIGHT,
          },
    };
  } else if (recreationalMode.type === 'hunted') {
    const huntedPlayer = Math.random() < 0.5 ? 'player1' : 'player2';
    huntedModeState = {
      huntedPlayer,
      timer: HUNTED_SURVIVE_TIME,
      announced: false,
    };
    showModeUnlockMessage(`${huntedPlayer === 'player1' ? 'Player 1' : 'Player 2'} is hunted. 90 second hunt begins.`);
  } else if (recreationalMode.type === 'borderShrink') {
    borderShrinkState = {
      timer: 0,
      damageTick: 0,
      axis: recreationalMode.axis === 'vertical' ? 'vertical' : 'horizontal',
      left: 0,
      right: getWorldWidth(),
      top: 0,
      bottom: getWorldHeight(),
    };
  } else if (isSwapMode()) {
    setupSwapFighter(player1);
    setupSwapFighter(player2);
    spawnSwapPickup();
    showModeUnlockMessage(isSwapWeaponMode()
      ? 'Weapon Swap: start with fists, then grab weapons.'
      : 'Ability Swap: grab up to two abilities.');
  } else if (recreationalMode.type === 'oneVsAll') {
    initializeOneVsAllMode();
  }
}

function scaleFighterHealth(fighter, multiplier) {
  if (!fighter?.parts) return;
  for (const part of Object.values(fighter.parts)) {
    part.max = +(part.max * multiplier).toFixed(1);
    part.cur = part.max;
  }
  if (fighter.characterTypeKey === 'royalPrince') {
    fighter.horseMaxHealth = +(fighter.horseMaxHealth * multiplier).toFixed(1);
    fighter.horseHealth = fighter.horseMaxHealth;
  }
}

function clearOneVsAllRoundObjects() {
  bombs.length = 0;
  bullets.length = 0;
  grenades.length = 0;
  magicFireballs.length = 0;
  hunterBolts.length = 0;
  hunterTraps.length = 0;
  royalArrows.length = 0;
  royalArrowParticles.length = 0;
  gunnerRockets.length = 0;
  frostSnowballs.length = 0;
  frostIcicles.length = 0;
  ashFlames.length = 0;
  ashTurrets.length = 0;
  stormZones.length = 0;
  stormShockwaves.length = 0;
  cosmicEvents.length = 0;
  cosmicHazards.length = 0;
  sorcererClones.length = 0;
  abyssalClones.length = 0;
}

function createOneVsAllFighter(typeKey, controls, side) {
  const fighter = new Fighter(0, 0, side === 'left' ? '#4ea6ff' : '#ff906d', controls, typeKey);
  fighter.controls = controls;
  fighter.oneVsAllAiState = createAiControllerState();
  const ground = getGroundY();
  const worldWidth = getWorldWidth();
  if (side === 'left') {
    fighter.x = 120;
    fighter.facing = 1;
  } else {
    fighter.x = worldWidth - 170;
    fighter.facing = -1;
  }
  fighter.y = ground - fighter.height;
  fighter.startX = fighter.x;
  fighter.startY = fighter.y;
  fighter.shieldDirection = fighter.getIdleShieldDirection();
  return fighter;
}

function initializeOneVsAllMode() {
  const soloOnLeft = Boolean(recreationalMode.soloOnLeft ?? recreationalMode.userIsSolo);
  const solo = soloOnLeft ? player1 : player2;
  const armyKeys = (recreationalMode.armyKeys || []).filter((key) => characterTypes[key]);
  const representedArmyFighter = soloOnLeft ? player2 : player1;
  representedArmyFighter.oneVsAllAiState = null;
  scaleFighterHealth(solo, 10);
  oneVsAllState = {
    userIsSolo: soloOnLeft,
    solo,
    army: [representedArmyFighter],
    armyKeys,
    currentIndex: 0,
    humanFighter: player1,
  };
  showModeUnlockMessage(`${solo.characterName} is the SOLO fighter on the ${soloOnLeft ? 'left' : 'right'}: 10x health gauntlet begins.`);
}

function spawnNextOneVsAllChallenger() {
  if (!isOneVsAllMode()) return false;
  oneVsAllState.currentIndex += 1;
  const nextKey = oneVsAllState.armyKeys[oneVsAllState.currentIndex];
  if (!nextKey) return false;
  const side = oneVsAllState.userIsSolo ? 'right' : 'left';
  const controls = oneVsAllState.userIsSolo ? player2Controls : player1Controls;
  const fighter = createOneVsAllFighter(nextKey, controls, side);
  clearOneVsAllRoundObjects();
  if (oneVsAllState.userIsSolo) {
    player2 = fighter;
  } else {
    player1 = fighter;
  }
  oneVsAllState.army = [fighter];
  oneVsAllState.humanFighter = oneVsAllState.userIsSolo ? oneVsAllState.solo : fighter;
  clearControlSet(fighter.controls);
  updateHealthUI();
  showModeUnlockMessage(`Next challenger: ${fighter.characterName} (${oneVsAllState.currentIndex + 1}/${oneVsAllState.armyKeys.length})`);
  return true;
}

function isOneVsAllMode() {
  return recreationalMode?.type === 'oneVsAll' && oneVsAllState;
}

function getAliveOneVsAllArmy() {
  return oneVsAllState?.army?.filter((fighter) => fighter && !fighter.dead) || [];
}

function getOneVsAllAllFighters() {
  if (!isOneVsAllMode()) return [player1, player2].filter(Boolean);
  return [oneVsAllState.solo, ...oneVsAllState.army].filter(Boolean);
}

function getOneVsAllTeam(fighter) {
  if (!isOneVsAllMode() || !fighter) return null;
  if (fighter === oneVsAllState.solo) return 'solo';
  if (oneVsAllState.army.includes(fighter)) return 'army';
  return null;
}

function isOneVsAllAIFighter(fighter) {
  return false;
}

function updateOneVsAllAIControls() {
  if (!isOneVsAllMode() || matchWinner) return;
  for (const fighter of getOneVsAllAllFighters()) {
    if (!isOneVsAllAIFighter(fighter)) continue;
    clearControlSet(fighter.controls);
    if (fighter.dead) continue;
    const target = getNearestOpposingTarget(fighter);
    if (!target) {
      continue;
    }
    if (!fighter.oneVsAllAiState) fighter.oneVsAllAiState = createAiControllerState();
    applyBossAIFighterControls(fighter, target, fighter.oneVsAllAiState);
  }
}

function updateOneVsAllExtraFighters() {
  if (!isOneVsAllMode() || matchWinner) return;
  for (const fighter of getOneVsAllAllFighters()) {
    if (fighter === player1 || fighter === player2 || fighter.dead) continue;
    fighter.update();
  }
}

function detectOneVsAllAttacks() {
  if (!isOneVsAllMode() || matchWinner) return;
  for (const attacker of getOneVsAllAllFighters()) {
    if (!attacker || attacker.dead) continue;
    if (attacker.attackBox && attacker.attackTimer > 6 && !attacker.hasHit) {
      const damage = getAttackDamage(attacker, getNearestOpposingTarget(attacker), attacker.characterTypeKey !== 'deadlySniper' && attacker.isCriticalHit());
      if (
        hitCloneWithBox(attacker, attacker.attackBox) ||
        hitGrimSoulWithBox(attacker, attacker.attackBox, damage, '#94ffe7') ||
        damageForestTreesWithBox(attacker, attacker.attackBox, damage, attacker.facing) ||
        damageOceanCreaturesWithBox(attacker, attacker.attackBox, damage)
      ) {
        attacker.hasHit = true;
        continue;
      }
    }
    for (const target of getOpposingTargets(attacker)) {
      resolveBossModeMeleeHit(attacker, target);
      if (attacker.hasHit) break;
    }
  }
}

function resolveOneVsAllWinner() {
  if (!isOneVsAllMode() || matchWinner) return !!matchWinner;
  const soloAlive = oneVsAllState.solo && !oneVsAllState.solo.dead;
  const challengerAlive = getAliveOneVsAllArmy().length > 0;
  if (soloAlive && challengerAlive) return false;
  if (soloAlive && !challengerAlive && spawnNextOneVsAllChallenger()) return false;
  matchWinner = soloAlive ? 'Solo' : 'Army';
  for (const fighter of getOneVsAllAllFighters()) {
    fighter.velocity.x = 0;
    fighter.velocity.y = 0;
    fighter.sniperAiming = false;
    fighter.royalBowAiming = false;
    fighter.gunnerRpgAiming = false;
    fighter.cosmicCollapseActive = false;
    fighter.abyssalWrathActive = false;
    stopRoyalChargeWind(fighter);
  }
  updateMatchReturnButton();
  playSound('victory', 250);
  return true;
}

function getRecreationalBorderBounds() {
  if (recreationalMode?.type === 'borderShrink' && borderShrinkState?.axis === 'horizontal') {
    return { left: borderShrinkState.left, right: borderShrinkState.right };
  }
  return { left: 0, right: getWorldWidth() };
}

function isFighterInKingZone(fighter) {
  if (!fighter || fighter.dead || !kingPlatformState?.zone) return false;
  const box = fighter.hitbox || { x: fighter.x, y: fighter.y, width: fighter.width, height: fighter.height };
  return rectIntersect(box, kingPlatformState.zone);
}

function finishRecreationalRuleMatch(winner) {
  if (matchWinner || !player1 || !player2) return;
  matchWinner = winner;
  player1.velocity.x = 0;
  player1.velocity.y = 0;
  player2.velocity.x = 0;
  player2.velocity.y = 0;
  updateMatchReturnButton();
  playSound('victory', 250);
}

function updateKingPlatformMode() {
  if (recreationalMode?.type !== 'kingPlatform' || !kingPlatformState || matchWinner) return;
  kingPlatformState.tick += 1;
  if (kingPlatformState.tick < KING_PLATFORM_SCORE_INTERVAL) return;
  kingPlatformState.tick = 0;
  const p1InZone = isFighterInKingZone(player1);
  const p2InZone = isFighterInKingZone(player2);
  if (p1InZone && !p2InZone) kingPlatformState.scores.player1 += 1;
  if (p2InZone && !p1InZone) kingPlatformState.scores.player2 += 1;
  if (kingPlatformState.scores.player1 >= KING_PLATFORM_SCORE_TO_WIN) finishRecreationalRuleMatch('Player 1');
  if (kingPlatformState.scores.player2 >= KING_PLATFORM_SCORE_TO_WIN) finishRecreationalRuleMatch('Player 2');
}

function updateHuntedMode() {
  if (recreationalMode?.type !== 'hunted' || !huntedModeState || matchWinner || !player1 || !player2) return;
  huntedModeState.timer = Math.max(0, huntedModeState.timer - 1);
}

function updateBorderShrinkMode() {
  if (recreationalMode?.type !== 'borderShrink' || !borderShrinkState || matchWinner) return;
  borderShrinkState.timer += 1;
  borderShrinkState.damageTick = (borderShrinkState.damageTick || 0) + 1;
  const worldWidth = getWorldWidth();
  const worldHeight = getWorldHeight();
  const progress = clamp((borderShrinkState.timer - BORDER_SHRINK_START_DELAY) / BORDER_SHRINK_DURATION, 0, 1);
  if (borderShrinkState.axis === 'vertical') {
    const currentHeight = worldHeight - (worldHeight - BORDER_SHRINK_MIN_HEIGHT) * progress;
    borderShrinkState.top = (worldHeight - currentHeight) / 2;
    borderShrinkState.bottom = borderShrinkState.top + currentHeight;
    borderShrinkState.left = 0;
    borderShrinkState.right = worldWidth;
  } else {
    const currentWidth = worldWidth - (worldWidth - BORDER_SHRINK_MIN_WIDTH) * progress;
    borderShrinkState.left = (worldWidth - currentWidth) / 2;
    borderShrinkState.right = borderShrinkState.left + currentWidth;
    borderShrinkState.top = 0;
    borderShrinkState.bottom = worldHeight;
  }
  if (borderShrinkState.damageTick >= BORDER_SHRINK_DAMAGE_INTERVAL) {
    borderShrinkState.damageTick = 0;
    for (const fighter of [player1, player2]) {
      if (!fighter || fighter.dead) continue;
      const box = fighter.hitbox || { x: fighter.x, y: fighter.y, width: fighter.width, height: fighter.height };
      const insideHorizontal = box.x >= borderShrinkState.left && box.x + box.width <= borderShrinkState.right;
      const insideVertical = box.y >= borderShrinkState.top && box.y + box.height <= borderShrinkState.bottom;
      if (insideHorizontal && insideVertical) continue;
      fighter.applySharedAreaDamage(BORDER_SHRINK_DAMAGE_PER_SECOND);
      if (borderShrinkState.axis === 'vertical') {
        const borderCenter = (borderShrinkState.top + borderShrinkState.bottom) / 2;
        const direction = box.y + box.height / 2 < borderCenter ? 1 : -1;
        addKnockback(fighter, 0, direction * 2);
      } else {
        const borderCenter = (borderShrinkState.left + borderShrinkState.right) / 2;
        const direction = box.x + box.width / 2 < borderCenter ? 1 : -1;
        addKnockback(fighter, direction * 2.5, -1.5);
      }
      hitEffects.push({
        x: box.x + box.width / 2,
        y: box.y + box.height / 2,
        timer: 18,
        maxTimer: 18,
        color: '#ff5f5f',
      });
    }
  }
}

function isSwapWeaponMode() {
  return recreationalMode?.type === 'swapWeapons';
}

function isSwapAbilityMode() {
  return recreationalMode?.type === 'swapAbilities';
}

function isSwapMode() {
  return isSwapWeaponMode() || isSwapAbilityMode();
}

function getSwapPickupPool() {
  if (isSwapWeaponMode()) return SWAP_WEAPON_POOL.map((key) => ({ type: 'weapon', key }));
  if (!isSwapAbilityMode()) return [];
  return [
    ...SWAP_PRIMARY_ABILITY_POOL.map((key) => ({ type: 'ability', slot: 'primary', key })),
    ...SWAP_SECONDARY_ABILITY_POOL.map((key) => ({ type: 'ability', slot: 'secondary', key })),
  ];
}

function getSwapPickupLabel(pickup) {
  const name = characterTypes[pickup?.key]?.name?.replace(/^The /, '') || 'Unknown';
  if (pickup?.type === 'weapon') return name;
  return `${pickup.slot === 'primary' ? 'Q' : 'R'} ${name}`;
}

function resetSwapWeaponResources(fighter) {
  if (!fighter) return;
  fighter.weaponLost = false;
  fighter.attackCooldown = 0;
  fighter.attackTimer = 0;
  fighter.hasHit = false;
  fighter.sniperAiming = false;
  fighter.royalBowAiming = false;
  fighter.gunnerRpgAiming = false;
  fighter.sniperAmmo = fighter.sniperMagazineSize;
  fighter.spyAmmo = fighter.spyMagazineSize;
  fighter.rifleAmmo = fighter.rifleMagazineSize;
  fighter.gunnerAmmo = fighter.gunnerMagazineSize;
  fighter.sniperReloadTimer = 0;
  fighter.spyReloadTimer = 0;
  fighter.rifleReloadTimer = 0;
  fighter.gunnerReloadTimer = 0;
  fighter.gunnerFireRamp = 0;
  fighter.gunnerSustainTimer = 0;
}

function setupSwapFighter(fighter) {
  if (!fighter) return;
  fighter.swapBaseCharacterTypeKey = fighter.swapBaseCharacterTypeKey || fighter.characterTypeKey;
  fighter.swapWeaponKey = null;
  fighter.swapAbilityKeys = [];
  if (isSwapWeaponMode()) fighter.weaponLost = true;
}

function getSwapSpawnPoint() {
  const floorY = getGroundY();
  const solidPlatforms = platforms.filter((platform) => !platform.oceanIsland && platform.width > 40);
  const roll = Math.random();
  const platform = solidPlatforms.length && roll < 0.35
    ? solidPlatforms[Math.floor(Math.random() * solidPlatforms.length)]
    : null;
  if (platform) {
    return {
      x: randomBetween(platform.x + SWAP_PICKUP_RADIUS + 8, platform.x + platform.width - SWAP_PICKUP_RADIUS - 8),
      y: platform.y - SWAP_PICKUP_RADIUS - randomBetween(9, 36),
    };
  }
  const x = randomBetween(80, Math.max(90, getWorldWidth() - 80));
  if (roll < 0.72) {
    const ceiling = isOceanMap() ? OCEAN_WATER_SURFACE_Y + 60 : 90;
    return {
      x,
      y: randomBetween(ceiling, Math.max(ceiling + 20, floorY - 95)),
    };
  }
  if (isRiverMap() && x > riverBounds.x && x < riverBounds.x + riverBounds.width) {
    return { x, y: getRiverSurfaceY() - SWAP_PICKUP_RADIUS - randomBetween(12, 60) };
  }
  return { x, y: floorY - SWAP_PICKUP_RADIUS - randomBetween(12, 64) };
}

function spawnSwapPickup() {
  const pool = getSwapPickupPool();
  if (!pool.length || swapPickups.length >= SWAP_MAX_PICKUPS) return;
  const choice = pool[Math.floor(Math.random() * pool.length)];
  const point = getSwapSpawnPoint();
  const portrait = createBossCharacterPortrait(choice.key, 58, 58);
  swapPickups.push({
    ...choice,
    x: point.x,
    y: point.y,
    radius: SWAP_PICKUP_RADIUS,
    portrait,
    pulse: Math.random() * Math.PI * 2,
  });
}

function collectSwapPickup(fighter, pickup) {
  if (!fighter || !pickup) return;
  if (pickup.type === 'weapon') {
    fighter.characterTypeKey = pickup.key;
    fighter.setCharacterType(pickup.key);
    fighter.swapWeaponKey = pickup.key;
    resetSwapWeaponResources(fighter);
    showModeUnlockMessage(`${fighter === player1 ? 'Player 1' : 'Player 2'} picked up ${getSwapPickupLabel(pickup)}.`);
  } else if (pickup.type === 'ability') {
    if (!Array.isArray(fighter.swapAbilityKeys)) fighter.swapAbilityKeys = [];
    const entry = { key: pickup.key, slot: pickup.slot };
    const otherSlot = pickup.slot === 'primary' ? 'secondary' : 'primary';
    const otherEntry = fighter.swapAbilityKeys.find((ability) => ability && ability.slot === otherSlot);
    fighter.swapAbilityKeys = otherEntry ? [otherEntry] : [];
    fighter.swapAbilityKeys.push(entry);
    showModeUnlockMessage(`${fighter === player1 ? 'Player 1' : 'Player 2'} picked up ${getSwapPickupLabel(pickup)}.`);
  }
  playSound('ui', 50);
}

function updateSwapPickups() {
  if (!isSwapMode() || matchWinner || !player1 || !player2) return;
  swapPickupSpawnTimer += 1;
  if (swapPickups.length < SWAP_MAX_PICKUPS && swapPickupSpawnTimer >= SWAP_PICKUP_SPAWN_INTERVAL) {
    swapPickupSpawnTimer = 0;
    spawnSwapPickup();
  }
  for (let i = swapPickups.length - 1; i >= 0; i--) {
    const pickup = swapPickups[i];
    const pickupBox = {
      x: pickup.x - pickup.radius,
      y: pickup.y - pickup.radius,
      width: pickup.radius * 2,
      height: pickup.radius * 2,
    };
    const collector = [player1, player2].find((fighter) => {
      if (!fighter || fighter.dead) return false;
      const box = fighter.hitbox || { x: fighter.x, y: fighter.y, width: fighter.width, height: fighter.height };
      return rectIntersect(box, pickupBox);
    });
    if (!collector) continue;
    collectSwapPickup(collector, pickup);
    swapPickups.splice(i, 1);
  }
}

function updateRecreationalRuleModes() {
  updateKingPlatformMode();
  updateHuntedMode();
  updateBorderShrinkMode();
  updateSwapPickups();
}

function updateGameAtCurrentSpeed() {
  updateRandomRecreationalSpeed();
  const speedScale = getRecreationalSpeedScale();
  const normalTiming =
    speedScale === 1 ||
    gamePaused ||
    characterIntroActive ||
    bossMode ||
    !player1 ||
    !player2 ||
    matchWinner;
  if (normalTiming) {
    recreationalSpeedAccumulator = 0;
    updateGame();
    return;
  }
  recreationalSpeedAccumulator += speedScale;
  let updates = 0;
  while (recreationalSpeedAccumulator >= 1 && updates < 5) {
    updateGame();
    recreationalSpeedAccumulator -= 1;
    updates += 1;
  }
  if (updates === 0) updateHealthUI();
}

