function getCharacterTutorialSteps(characterKey) {
  const info = CHARACTER_TUTORIAL_INFO[characterKey];
  if (!info) return null;
  const characterName = characterTypes[characterKey]?.name || 'This character';
  const steps = [
    {
      title: 'Regular Attack',
      text: info.attack,
      type: 'attackDamage',
      targetPart: 'torso',
    },
  ];
  if (info.feat) {
    steps.push({
      title: 'Special Feat',
      text: info.feat,
      type: 'info',
      duration: 10 * FPS,
    });
  }
  if (characterKey === 'swordMaster') {
    steps.push({
      title: 'Falling Crit',
      text: 'Jump, start falling, then press S into the dummy. A falling crit deals 8 damage and tries to punish the head when the swing lines up.',
      type: 'critDamage',
      targetPart: 'head',
    });
  }
  steps.push(
    {
      title: 'First Ability',
      text: info.primary,
      type: 'primaryInput',
    },
    {
      title: 'Second Ability',
      text: info.secondary,
      type: 'secondaryInput',
    },
    {
      title: 'Free Practice',
      text: `The dummy is moving now. Play around with ${characterName} for as long as you want, then use the exit button when you are done.`,
      type: 'freePractice',
    }
  );
  return steps;
}
