function getAdminControlValues(characterKey) {
  const baseHealth = getBasePartHealthConfig(characterKey);
  const tuning = getAdminTuning(characterKey) || {};
  const values = {
    overallHealth: tuning.overallHealth ?? getDefaultOverallHealth(characterKey),
    headHealth: tuning.headHealth ?? baseHealth.head,
    torsoHealth: tuning.torsoHealth ?? baseHealth.torso,
    limbHealth: tuning.limbHealth ?? baseHealth.limbs,
    regularDamage: tuning.regularDamage ?? getDefaultRegularAttackDamage(characterKey),
    walkSpeed: tuning.walkSpeed ?? getDefaultWalkSpeed(characterKey),
    attackCooldownFrames: tuning.attackCooldownFrames ?? getDefaultAttackCooldownFrames(characterKey),
    primaryCooldownSeconds: tuning.primaryCooldownSeconds ?? getAdminPanelPrimaryCooldownBase(characterKey) / FPS,
    secondaryCooldownSeconds: tuning.secondaryCooldownSeconds ?? getAdminPanelSecondaryCooldownBase(characterKey) / FPS,
  };
  for (const [key, , , fallback] of getAdminSpecificFieldDefs(characterKey)) {
    values[key] = tuning[key] ?? fallback;
  }
  return values;
}

function renderAdminControlPanel() {
  if (!adminControlCharacterSelect || !adminControlFields) return;
  if (!adminControlCharacterSelect.options.length) {
    for (const key of getAdminControlCharacterKeys()) {
      const option = document.createElement('option');
      option.value = key;
      option.textContent = characterTypes[key]?.name || key;
      adminControlCharacterSelect.appendChild(option);
    }
  }
  const characterKey = adminControlCharacterSelect.value || getAdminControlCharacterKeys()[0];
  if (!adminControlCharacterSelect.value) adminControlCharacterSelect.value = characterKey;
  const values = getAdminControlValues(characterKey);
  const fieldDefs = [
    ...getAdminCoreFieldDefs(characterKey),
    ...getAdminSpecificFieldDefs(characterKey),
  ];
  adminControlFields.innerHTML = '';
  for (const [key, label, hint] of fieldDefs) {
    const wrapper = document.createElement('div');
    wrapper.className = 'admin-control-field';
    wrapper.innerHTML = `
      <label for="admin-control-${key}">${label}</label>
      <input id="admin-control-${key}" data-admin-control-key="${key}" type="number" step="0.01" min="0" value="${formatAdminControlNumber(values[key])}">
      <div class="admin-control-hint">${hint}</div>
    `;
    adminControlFields.appendChild(wrapper);
  }
}

function openAdminControlPanel() {
  if (!adminUnlockActive) {
    showModeUnlockMessage('Character Control Panel is available after Admin Unlock.');
    return;
  }
  renderAdminControlPanel();
  adminControlPanel?.classList.remove('hidden');
  playSound('ui', 40);
}

function closeAdminControlPanel() {
  adminControlPanel?.classList.add('hidden');
}

function applyAdminControlPanelChanges() {
  const characterKey = adminControlCharacterSelect?.value;
  if (!characterKey) return;
  const next = {};
  adminControlFields?.querySelectorAll('[data-admin-control-key]').forEach((input) => {
    const key = input.dataset.adminControlKey;
    const value = Number(input.value);
    if (Number.isFinite(value) && value >= 0) next[key] = value;
  });
  adminTuningOverrides[characterKey] = next;
  showModeUnlockMessage(`${characterTypes[characterKey]?.name || characterKey} temporary tuning applied.`);
  renderAdminControlPanel();
}

function resetSelectedAdminControlPanelChanges() {
  const characterKey = adminControlCharacterSelect?.value;
  if (!characterKey) return;
  delete adminTuningOverrides[characterKey];
  renderAdminControlPanel();
  showModeUnlockMessage(`${characterTypes[characterKey]?.name || characterKey} tuning reset.`);
}

function resetAllAdminControlPanelChanges() {
  for (const key of Object.keys(adminTuningOverrides)) delete adminTuningOverrides[key];
  renderAdminControlPanel();
  showModeUnlockMessage('All temporary character tuning reset.');
}

function activateAdminUnlock() {
  const newlyUnlockedKeys = CHARACTER_UNLOCK_ORDER.filter((key) => {
    return key !== 'swordMaster' && (progression.shards[key] || 0) < SHARDS_TO_UNLOCK;
  });
  adminUnlockActive = true;
  adminSessionBossClears.clear();
  for (const level of BOSS_LEVELS) adminSessionBossClears.add(level.key);
  selectedBossLevelKey = 'treeMonster';
  bossDraftOpen = false;
  for (const key of CHARACTER_UNLOCK_ORDER) progression.shards[key] = SHARDS_TO_UNLOCK;
  progression.gold = Math.max(progression.gold, ADMIN_TEST_GOLD);
  saveProgression();
  for (const key of newlyUnlockedKeys) seenCharacterIntros.delete(key);
  saveSeenCharacterIntros();
  updateScoreUI();
  queueCharacterIntros(newlyUnlockedKeys);
  adminPasswordInput.value = '';
  adminPasswordStatusEl.textContent = '';
  adminPasswordStatusEl.classList.remove('error');
  adminCharacterUnlockEl.hidden = true;
  showAdminUnlockButton.textContent = 'Admin Unlock Active';
  showAdminUnlockButton.disabled = true;
}

