function getPartHealthConfig(characterTypeKey) {
  const base = getBasePartHealthConfig(characterTypeKey);
  const tuning = getAdminTuning(characterTypeKey);
  if (!tuning) return base;
  if (hasOverallHealthOnly(characterTypeKey)) {
    const overallHealth = getAdminTuningNumber(characterTypeKey, 'overallHealth', getDefaultOverallHealth(characterTypeKey));
    return {
      head: overallHealth,
      torso: overallHealth,
      limbs: overallHealth,
    };
  }
  return {
    head: getAdminTuningNumber(characterTypeKey, 'headHealth', base.head),
    torso: getAdminTuningNumber(characterTypeKey, 'torsoHealth', base.torso),
    limbs: getAdminTuningNumber(characterTypeKey, 'limbHealth', base.limbs),
  };
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function formatHealth(value) {
  return Number.isInteger(value) ? `${value}` : value.toFixed(1);
}

