function hideRosterScreen() {
  rosterScreen?.classList.add('hidden');
}

function startBossModeFight(options = {}) {
  const forcedTypes = Array.isArray(options.selectedTypesOverride) ? options.selectedTypesOverride.filter(Boolean) : null;
  if (!bossDraftOpen && !forcedTypes) {
    playSound('ui', 40);
    return;
  }
  const selectedTypes = forcedTypes || bossFormationSelections.filter(Boolean);
  if (selectedTypes.length < getBossDeployCount() || new Set(selectedTypes).size !== selectedTypes.length) {
    playSound('ui', 40);
    return;
  }
  if (forcedTypes) bossFormationSelections = selectedTypes.slice(0, getBossDeployCount());
  lastBossFormationSelections = selectedTypes.slice(0, getBossDeployCount());
  bossMode = true;
  aiMode = false;
  tournamentMode = false;
  tournamentFinished = false;
  hideBossFormationScreen();
  const requestedBossType = BOSS_LEVELS.some((level) => level.key === selectedBossLevelKey)
    ? selectedBossLevelKey
    : 'treeMonster';
  const bossType = isBossLevelUnlocked(requestedBossType) ? requestedBossType : 'treeMonster';
  selectedBossLevelKey = bossType;
  if (bossType === 'betrayalBoss' && !hasFullPlayableRoster()) {
    showModeUnlockMessage('The Betrayal requires the full roster.');
    playSound('ui', 40);
    bossMode = false;
    return;
  }
  setupPlayers(selectedTypes[0], bossType, 'random');
  bossMode = true;
  player2.x = getWorldWidth() - 210;
  player2.y = getGroundY() - player2.height;
  player2.facing = -1;
  player2.abilityCooldown = player2.getPrimaryAbilityCooldownMax();
  player2.ghostInvisibilityCooldown = GHOST_INVISIBILITY_COOLDOWN;
  player2.ghostInvisibleTimer = 0;
  bossGhostClones = [];
  transformerBossState = null;
  infestedHospitalBossState = null;
  elementalWizardBossState = null;
  giantSpiderBossState = null;
  sandTyrantBossState = null;
  necroGeneralBossState = null;
  mirrorMonkBossState = null;
  voidWardenBossState = null;
  bombManiacBombs.length = 0;
  bloodAlchemistVials.length = 0;
  bloodAlchemistPools.length = 0;
  transformerBossBullets.length = 0;
  transformerBossRockets.length = 0;
  bossSquad = [];
  betrayalBossEnemies = [];
  bossAIStates = [];
  bossFormationReleased = false;
  const formationSlots = [
    { x: 335, y: 0 },
    { x: 235, y: 0 },
    { x: 245, y: -14 },
    { x: 105, y: 0 },
    { x: 120, y: -14 },
  ];
  selectedTypes.forEach((typeKey, index) => {
    const controls = index === 0 ? player1Controls : createBossControls(index);
    const surfaceY = getGroundY();
    const fighter = index === 0
      ? player1
      : new Fighter(0, 0, '#4ea6ff', controls, typeKey);
    fighter.characterTypeKey = typeKey;
    fighter.setCharacterType(typeKey);
    fighter.width = getFighterWidth(typeKey);
    fighter.height = getFighterHeight(typeKey);
    fighter.initParts();
    const slot = formationSlots[index] || formationSlots[formationSlots.length - 1];
    fighter.x = slot.x;
    fighter.y = surfaceY - fighter.height + slot.y;
    fighter.startX = fighter.x;
    fighter.startY = fighter.y;
    fighter.facing = 1;
    fighter.controls = controls;
    fighter.bossShieldHeld = false;
    bossSquad.push(fighter);
    bossAIStates.push({ decisionTimer: index * 5, attackHold: 0 });
  });
  player1 = bossSquad[0];
  bossActiveIndex = 0;
  if (bossType === 'transformerBoss') {
    initializeTransformerBoss();
  } else if (bossType === 'elementalWizard') {
    initializeElementalWizardBoss();
  } else if (bossType === 'giantSpider') {
    initializeGiantSpiderBoss();
  } else if (bossType === 'sandTyrant') {
    initializeSandTyrantBoss();
  } else if (bossType === 'necroGeneral') {
    initializeNecroGeneralBoss();
  } else if (bossType === 'returnButtonBoss') {
    initializeReturnButtonBoss();
    if (options.returnButtonImmediateFight) activateReturnButtonBossImmediateFight();
  } else if (bossType === 'mirrorMonk') {
    initializeMirrorMonkBoss();
  } else if (bossType === 'voidWarden') {
    initializeVoidWardenBoss();
  } else if (bossType === 'betrayalBoss') {
    initializeBetrayalBoss(selectedTypes);
  }
  clearBossSquadControls();
  clearAIControls();
  bossCountdownTimer = options.skipCountdown ? 0 : 3 * FPS;
  setRestartButtonMode('Exit Boss Fight');
  updateHealthUI();
}

