function startMapChoiceMatch() {
  const selectedMap = mapSelect?.value || 'classic';
  if (!isMapUnlocked(selectedMap)) {
    showModeUnlockMessage('This map is still locked.');
    updateMapUnlocks();
    playSound('ui', 40);
    return;
  }
  aiMode = pendingRecreationalMode ? false : pendingMapChoiceAI;
  aiDuelMode = false;
  aiDuelStateP1 = null;
  aiDuelStateP2 = null;
  if (aiMode) aiDifficulty = aiDifficultySelect.value;
  recreationalMode = pendingRecreationalMode;
  recreationalSpeedAccumulator = 0;
  tournamentMode = false;
  tournamentFinished = false;
  setRestartButtonMode('Exit Match');
  updateTournamentStatus();
  updateGameModeLabels();
  if (!recreationalMode && scoresAreZeroZero() && !tutorialDismissedThisSession && !adminUnlockActive) {
    startTutorialMatch();
    return;
  }
  if (recreationalMode?.type === 'oneVsAll') {
    setupPlayers(recreationalMode.player1Key || recreationalMode.chosenKey, recreationalMode.player2Key || recreationalMode.soloKey);
  } else if (recreationalMode?.type === 'draft') {
    setupPlayers(recreationalMode.player1Key || 'swordMaster', recreationalMode.player2Key || 'swordMaster');
  } else if (aiMode) {
    setupPlayers(null, getRandomTournamentCharacter());
  } else {
    setupPlayers();
  }
  initializeRecreationalRuleState();
}

