function startTournament(playAgainstAI = false) {
  clearRecreationalMode();
  if (playAgainstAI && progression.gold < TOURNAMENT_ENTRY_FEE) {
    showModeUnlockMessage(`Tournament entry costs ${TOURNAMENT_ENTRY_FEE.toLocaleString()} gold.`);
    playSound('ui', 40);
    return;
  }
  if (playAgainstAI) {
    progression.gold -= TOURNAMENT_ENTRY_FEE;
    saveProgression();
    updateScoreUI();
  }
  aiMode = playAgainstAI;
  aiDuelMode = false;
  aiDuelStateP1 = null;
  aiDuelStateP2 = null;
  bossMode = false;
  betrayalBossEnemies = [];
  if (aiMode) aiDifficulty = tournamentAiDifficultySelect?.value || aiDifficultySelect.value;
  tournamentMode = true;
  tournamentRound = 0;
  tournamentWins = { player1: 0, player2: 0 };
  tournamentFinished = false;
  hideTournamentOpponentChoice();
  updateGameModeLabels();
  startNextTournamentRound();
}

function startNextTournamentRound() {
  if (!tournamentMode || tournamentFinished) return;
  if (isTournamentSeriesComplete()) {
    tournamentFinished = true;
    updateTournamentStatus();
    return;
  }
  matchWinner = null;
  tournamentRound = getTournamentNextRoundNumber();
  setRestartButtonMode('Exit Tournament');
  updateMatchReturnButton();
  setupPlayers(getRandomTournamentCharacter(), getRandomTournamentCharacter(), getRandomTournamentMap());
  updateTournamentStatus();
}

function endTournamentMode() {
  aiMode = false;
  clearRecreationalMode();
  tournamentMode = false;
  tournamentFinished = false;
  tournamentRound = 0;
  tournamentWins = { player1: 0, player2: 0 };
  setRestartButtonMode('Exit Match');
  updateTournamentStatus();
  hideTournamentOpponentChoice();
  showStartScreen();
}

