function renderStartLogoCast() {
  const groups = [
    { root: startLogoLeftCast, keys: ['swordMaster', 'armoredKnight', 'deadlySniper'] },
    { root: startLogoRightCast, keys: ['stormRonin', 'frostValkyrie', 'abyssalDemon'] },
  ];
  for (const group of groups) {
    if (!group.root || group.root.dataset.rendered === 'true') continue;
    group.root.innerHTML = '';
    group.keys.forEach((key, index) => {
      const frame = document.createElement('div');
      frame.className = `start-logo-character char-${index}`;
      frame.title = characterTypes[key]?.name || key;
      const portrait = createBossCharacterPortrait(key, 118, 130);
      portrait.className = 'start-logo-character-canvas';
      frame.appendChild(portrait);
      group.root.appendChild(frame);
    });
    group.root.dataset.rendered = 'true';
  }
}

