resetAiDuelStatsButton?.addEventListener('click', () => {
  const confirmed = window.confirm('Reset the AI duel leaderboard?');
  if (!confirmed) return;
  aiDuelStats = createDefaultAiDuelStats();
  for (const room of aiDuelRooms) {
    room.roomWins = { player1: 0, player2: 0 };
    room.games = 0;
  }
  saveAiDuelStats();
  renderAiDuelLeaderboard();
  renderAiDuelRooms();
  playSound('ui', 40);
});

function handleAiDuelRoomPointer(event, requireActiveDuel = false) {
  const roomButton = event.target.closest?.('.ai-duel-room');
  if (!roomButton) return false;
  const index = Number(roomButton.dataset.roomIndex);
  if (!Number.isFinite(index)) return false;
  event.preventDefault();
  playSound('ui', 35);
  if (!aiDuelMode) {
    if (requireActiveDuel) return true;
    startAiDuelMatch();
    return true;
  }
  observeAiDuelRoom(index);
  return true;
}

aiDuelRoomsEl?.addEventListener('pointerdown', (event) => {
  handleAiDuelRoomPointer(event, false);
});

aiDuelRoomOverlay?.addEventListener('pointerdown', (event) => {
  handleAiDuelRoomPointer(event, true);
});

