resetScoresButton.addEventListener('click', () => {
  const confirmed = window.confirm(
    'Reset all account progress?\n\nThis will wipe gold, shards, unlocked characters, boss progress, and scores. This cannot be undone.'
  );
  if (!confirmed) return;
  playSound('ui', 40);
  adminUnlockActive = false;
  adminSessionBossClears.clear();
  selectedBossLevelKey = 'treeMonster';
  bossDraftOpen = false;
  scores = { player1: 0, player2: 0 };
  progression = createDefaultProgression();
  clearReturnButtonBossRematchTimer();
  seenCharacterIntros.clear();
  saveScores();
  saveProgression();
  saveSeenCharacterIntros();
  try {
    localStorage.removeItem(BOSS_PROGRESS_STORAGE_KEY);
  } catch {
    // Boss progress still resets for this session if storage is unavailable.
  }
  updateScoreUI();
  tutorialDismissedThisSession = false;
});

