player2CharacterSelect.dataset.lastValue = player2CharacterSelect.value;
player1CharacterSelect.addEventListener('change', () => handleCharacterSelection(player1CharacterSelect));
player2CharacterSelect.addEventListener('change', () => handleCharacterSelection(player2CharacterSelect));
function collapseCharacterSelect(selectEl) {
  if (!selectEl) return;
  selectEl.size = 1;
}

function expandCharacterSelect(selectEl) {
  if (!selectEl) return;
  selectEl.size = Math.min(5, selectEl.options.length);
}

for (const selectEl of [player1CharacterSelect, player2CharacterSelect, oneVsAllCharacterSelect].filter(Boolean)) {
  collapseCharacterSelect(selectEl);
  selectEl.addEventListener('pointerdown', () => {
    expandCharacterSelect(selectEl);
  });
  selectEl.addEventListener('focus', () => expandCharacterSelect(selectEl));
  selectEl.addEventListener('blur', () => {
    collapseCharacterSelect(selectEl);
  });
  selectEl.addEventListener('change', () => {
    collapseCharacterSelect(selectEl);
    selectEl.blur();
  });
}

